const PREFIX = { p: 'place-', t: 'thinker-', i: 'idea-' };
const ref = (s) => {
  const m = /^([pti]):(.+)$/.exec(s);
  return m ? PREFIX[m[1]] + m[2] : s;
};
const mk = (category, prefix) => (id, label, era, tags, quote, summary) => ({
  id: prefix + id,
  label,
  category,
  era,
  summary,
  quote: quote || null,
  tags,
});
const P = mk('place', 'place-');
const I = mk('idea', 'idea-');
const T = mk('thinker', 'thinker-');

