NODES.push(
  // ---- Places
  P('bukhara', 'Bukhara', 'Samanid & Timurid Eras (9th - 16th c.)', ['bukhara', 'uzbekistan', 'central-asia', 'islamic', 'hadith', 'sufism', 'jadidism'], null,
    'Bukhara, the “Noble” city on the Silk Road, was a capital of the Samanid state and a pillar of Islamic scholarship. It produced Ibn Sina’s earliest training, al-Bukhari’s hadith canon, the Naqshbandi Sufi order, and in the early 20th century a vibrant Jadid reform movement.'),
  P('samarkand', 'Samarkand', 'Timurid Renaissance (14th - 15th c.)', ['samarkand', 'uzbekistan', 'central-asia', 'islamic', 'astronomy', 'timurid'], null,
    'Samarkand, the jewel of Timur’s empire, became under Ulugh Beg a centre of mathematical astronomy, with an observatory whose star catalogue was the finest of its age. It was also a hub of madrasa education and Silk Road exchange between Persian, Turkic, Chinese and Indian learning.'),
  P('khwarezm', 'Khwarezm (Khiva & Kath)', 'Islamic Golden Age (8th - 13th c.)', ['khwarezm', 'uzbekistan', 'central-asia', 'islamic', 'mathematics', 'science'], null,
    'Khwarezm, the oasis land along the lower Amu Darya, gave the world al-Khwarizmi, the founder of algebra, and al-Biruni, a polymath of astronomy, geodesy and comparative religion. Its scholars linked the Abbasid centre in Baghdad with Central Asia and India.'),
  P('nishapur-tus', 'Nishapur & Tus (Khorasan)', 'Seljuk Era (10th - 12th c.)', ['nishapur', 'tus', 'persia', 'khorasan', 'islamic', 'sufism'], null,
    'Khorasan’s great cities Nishapur and Tus nurtured al-Ghazali, Omar Khayyam, Attar and Nasir al-Din Tusi. Their madrasas, observatories and Sufi lodges made the region a crucible where law, theology, poetry and science met.'),
  P('isfahan-shiraz', 'Isfahan & Shiraz (Persia)', 'Safavid & Classical Persian Era', ['isfahan', 'shiraz', 'persia', 'islamic', 'illuminationism', 'sufism'], null,
    'Isfahan and Shiraz were the intellectual heart of Persian philosophy and poetry, from Hafez’s lyric mysticism to the Isfahan School of Mir Damad and Mulla Sadra. Here Avicennan metaphysics, Suhrawardi’s Illuminationism and Ibn Arabi’s gnosis were fused into a new “Transcendent Wisdom”.'),
  P('konya', 'Konya', 'Seljuk Anatolia (13th c.)', ['konya', 'anatolia', 'turkey', 'sufism', 'islamic', 'mevlevi'], null,
    'Konya, capital of the Seljuk Sultanate of Rum, was the home of Rumi and the Mevlevi order, the “whirling dervishes”. Ibn Arabi’s disciple Sadr al-Din al-Qunawi taught here too, making the city a meeting point of Persian poetry and Andalusian metaphysics.'),
  P('damascus', 'Damascus', 'Umayyad to Mamluk Eras', ['damascus', 'syria', 'islamic', 'sufism', 'theology'], null,
    'Damascus, the Umayyad capital, remained a major seat of Islamic learning for a thousand years. It sheltered Ibn Arabi in his last decades, was the home of Ibn Taymiyya’s fierce theological campaigns, and hosted al-Farabi and many hadith scholars.'),
  P('cairo', 'Cairo (al-Azhar)', 'Fatimid to Modern Eras', ['cairo', 'egypt', 'islamic', 'al-azhar', 'modernism', 'judaism'], null,
    'Cairo, home of al-Azhar (founded 970), was where Maimonides wrote the Guide of the Perplexed and where Muhammad Abduh led Islamic modernist reform in the 19th century. It remains a leading centre for Sunni scholarship and debates over tradition and modernity.'),
  P('constantinople', 'Constantinople / Istanbul', 'Byzantine & Ottoman Eras (330 - 1922)', ['constantinople', 'istanbul', 'byzantium', 'ottoman', 'orthodox', 'islamic'], null,
    'Constantinople preserved Greek learning for a millennium as capital of the Byzantine Empire, and after 1453 became the Ottoman capital. Its scholars Psellos and Plethon revived Platonism, and its migrants carried Greek manuscripts to Renaissance Italy.'),
  P('mount-athos', 'Mount Athos', 'Byzantine to Present', ['athos', 'byzantium', 'orthodox', 'hesychasm', 'mysticism', 'greece'], null,
    'Mount Athos, the “Holy Mountain” of Orthodox monasticism, was the home of the Hesychast tradition of silent prayer defended by Gregory Palamas. It stands as a living archive of Byzantine theology, contemplation and manuscript culture.'),
  P('timbuktu', 'Timbuktu & the Sahel', 'Songhai Era (14th - 16th c.)', ['timbuktu', 'mali', 'west-africa', 'islamic', 'manuscripts', 'africa'], null,
    'Timbuktu was a great West African centre of Islamic learning, with the Sankore madrasa and tens of thousands of manuscripts on law, astronomy, medicine and ethics. It shows how scholarship flowed across the Sahara between Maghreb, Egypt and the Sahel.'),
  P('delhi', 'Delhi & Mughal India', 'Delhi Sultanate to Modern India', ['delhi', 'india', 'mughal', 'islamic', 'sufism', 'indian'], null,
    'Delhi, capital of successive sultanates and the Mughal Empire, was a meeting place of Persian, Arabic and Indic thought, from the Chishti Sufis to Shah Waliullah’s reform of Islamic thought. In the modern era it became the political centre of Indian independence and philosophy.'),
  P('lahore', 'Lahore', '19th - 20th Century', ['lahore', 'pakistan', 'islamic', 'modernism', 'poetry', 'punjab'], null,
    'Lahore, cultural capital of the Punjab, was the home of Muhammad Iqbal, whose philosophical poetry reconstructed Islamic thought in dialogue with Nietzsche, Bergson and Hegel. The city links Persian literary tradition to the intellectual politics of modern South Asia.'),
  P('london', 'London', 'Modern Era', ['london', 'england', 'british', 'enlightenment', 'empire', 'modernism'], null,
    'London has been a site of radical thought from Wollstonecraft’s circle to Marx writing Capital in the British Museum reading room. Coffeehouses, the Royal Society and the London School of Economics made it a hub for science, political economy and analytic philosophy.'),
  P('dublin', 'Dublin (Trinity College)', '17th - 18th Century', ['dublin', 'ireland', 'empiricism', 'enlightenment', 'british'], null,
    'Trinity College Dublin was the university of George Berkeley, Edmund Burke and Jonathan Swift. Its “Irish Enlightenment” gave empiricism its most radical idealist twist and conservatism its most eloquent voice.'),
  P('beijing', 'Neo-Confucian China (Song & Ming)', 'Song - Ming Dynasties (960 - 1644)', ['china', 'neo-confucianism', 'chinese', 'song-dynasty', 'ming-dynasty'], null,
    'During the Song and Ming dynasties, Confucian scholars such as Zhu Xi and Wang Yangming absorbed Buddhist and Daoist metaphysics into a new Neo-Confucian synthesis. Its academies shaped state examinations and East Asian thought for six centuries.'),
  P('tokyo', 'Tokyo & Modern Japan', 'Meiji to Present', ['tokyo', 'japan', 'japanese', 'modernism', 'kyoto-school'], null,
    'Modern Japan translated Western philosophy into a new vocabulary during the Meiji era and produced thinkers such as Watsuji Tetsuro and Nishitani Keiji. Its philosophers negotiated the tension between Western modernity and Buddhist-Confucian heritage.'),
  P('naples', 'Naples', 'Medieval to Enlightenment', ['naples', 'italy', 'italian', 'scholasticism', 'humanism', 'enlightenment'], null,
    'Naples, with its university founded in 1224, trained Thomas Aquinas, hosted Giordano Bruno’s early heresies and was the home of Giambattista Vico. The city’s layered Greek, Roman, Norman and Spanish history inspired a distinctly historical, imaginative philosophy.'),
  P('salamanca', 'Salamanca', 'Spanish Golden Age', ['salamanca', 'spain', 'natural-law', 'scholasticism', 'human-rights', 'spanish'], null,
    'The School of Salamanca, led by Francisco de Vitoria and Domingo de Soto, developed early doctrines of international law, natural rights and just war. Its debates over the conquest of the Americas anticipated modern human-rights thinking, and its economists wrote early monetary theory.'),
  P('moscow', 'Moscow', 'Russian Philosophical Renaissance', ['moscow', 'russia', 'russian', 'orthodox', 'cosmism', 'philosophy'], null,
    'Moscow was the centre of Slavophile salons, Solovyov’s Neoplatonic Christianity and Fedorov’s cosmism. Moscow University and the Religious-Philosophical Society fostered the “Silver Age” of Russian thought.'),
  P('st-petersburg', 'St Petersburg', 'Imperial & Silver Age Russia', ['petersburg', 'russia', 'russian', 'westernizers', 'literature', 'silver-age'], null,
    'Peter the Great’s “window on Europe” became the home of the Westernizers, Dostoevsky’s urban nightmares and Bakhtin’s early dialogism. It was the stage for debates on whether Russia belongs to Europe or follows its own path.'),
  P('africa', 'Africa (Akan, Yoruba & Nguni Thought)', 'Oral Tradition to Present', ['africa', 'african', 'ubuntu', 'decolonial', 'communitarianism'], null,
    'African philosophy is rooted in oral traditions of Akan, Yoruba, Igbo and Nguni peoples, which stress community, personhood and moral relationality. Contemporary thinkers like Kwasi Wiredu and Kwame Gyekye articulated these ideas in dialogue with analytic philosophy and decolonial theory.'),
  P('latin-america', 'Latin America (Mexico City & Beyond)', 'Colonial Era to Present', ['latin-america', 'decolonial', 'liberation', 'spanish', 'indigenous'], null,
    'From Sor Juana’s convent in Mexico City to Paulo Freire’s literacy campaigns in Brazil, Latin America produced philosophies of liberation, education and decolonial critique. Its thinkers insisted that philosophy be tested by the lives of the oppressed.'),
  P('silicon-valley', 'Silicon Valley & Bay Area', '20th - 21st Century', ['silicon-valley', 'california', 'technology', 'futurism', 'ai', 'american'], null,
    'Silicon Valley turned the cybernetic and counter-cultural dreams of the 1960s into global technology industries. It is the main stage for debates about artificial intelligence, transhumanism, effective altruism and the social cost of digital platforms.'),

  // ---- Ideas
  I('kalam', 'Kalam (Islamic Theology)', '8th - 15th Century', ['kalam', 'islamic', 'theology', 'reason', 'ashari', 'maturidi'], null,
    'Kalam is the Islamic tradition of dialectical theology, which defends the doctrines of revelation using rational argument. The Mu‘tazila stressed divine justice and human freedom, while the Ash‘ari and Maturidi schools gave later Sunni orthodoxy its systematic form, including debates on atomism, causation and the createdness of the Qur’an.'),
  I('islamic-philosophy', 'Falsafa (Islamic Peripatetic Philosophy)', '9th - 12th Century', ['islamic-philosophy', 'falsafa', 'islamic', 'aristotelianism', 'neoplatonism', 'logic'], null,
    'Falsafa is the philosophy of al-Kindi, al-Farabi, Ibn Sina and Ibn Rushd, which merged Aristotelian logic and physics with Neoplatonic emanation and Islamic monotheism. Translated into Latin, it shaped the scholastic debates of Paris and Oxford.'),
  I('sufism', 'Sufism & Islamic Mysticism', '8th Century - Present', ['sufism', 'mysticism', 'islamic', 'love', 'persia', 'gnosis'], null,
    'Sufism is the mystical dimension of Islam, centred on purification of the heart, love of the Divine and direct experiential knowledge (ma‘rifa). From Rabia and al-Hallaj to Rumi and Ibn Arabi, Sufis developed rich traditions of poetry, metaphysics and spiritual discipline through orders such as the Naqshbandi, Mevlevi and Qadiri.'),
  I('illuminationism', 'Illuminationism (Ishraq)', '12th Century', ['illuminationism', 'ishraq', 'persia', 'islamic', 'light', 'platonism'], null,
    'Illuminationism, founded by Suhrawardi, holds that reality is a hierarchy of light, and that true knowledge arises from direct illumination rather than from definition alone. It fused Platonism, Zoroastrian angelology and Avicennan logic into a visionary Persian philosophy.'),
  I('transcendent-theosophy', 'Transcendent Theosophy (al-Hikma al-Muta‘aliya)', '17th Century', ['transcendent-theosophy', 'persia', 'islamic', 'metaphysics', 'being', 'mulla-sadra'], null,
    'Mulla Sadra’s “Transcendent Wisdom” makes existence prior to essence and sees reality as a graded, dynamic flow (substantial motion). It united peripatetic reasoning, illumination and Sufi gnosis, and has been compared to later existentialism and process philosophy.'),
  I('islamic-science', 'Islamic Golden Age Science', '8th - 15th Century', ['islamic-science', 'islamic', 'mathematics', 'astronomy', 'medicine', 'optics'], null,
    'Scholars working in Arabic from Baghdad to Samarkand and Córdoba made lasting advances in algebra, optics, astronomy and medicine, relying on translation, observation and experiment. Their works supplied the foundations for the European scientific Renaissance.'),
  I('islamic-modernism', 'Islamic Modernism & Reform', '19th - 21st Century', ['islamic-modernism', 'islamic', 'reform', 'modernism', 'politics', 'ijtihad'], null,
    'Islamic modernism seeks to reconcile revelation with modern science, constitutionalism and rights through renewed independent reasoning (ijtihad). Figures such as al-Afghani, Abduh and Iqbal, followed by Fazlur Rahman and Soroush, debated how to reform without losing tradition.'),
  I('jadidism', 'Jadidism (Central Asian Reform)', 'Late 19th - Early 20th Century', ['jadidism', 'uzbekistan', 'central-asia', 'reform', 'education', 'islamic'], null,
    'Jadidism was a Muslim reform and enlightenment movement in Russian-ruled Central Asia and the Volga region. Its “new-method” schools, newspapers and theatre promoted literacy, science and national awakening, and its leaders such as Behbudi and Fitrat were later repressed in the Soviet purges.'),
  I('zoroastrianism', 'Zoroastrianism & Persian Dualism', 'c. 1500 BC - Present', ['zoroastrianism', 'persia', 'dualism', 'ethics', 'ancient'], null,
    'Zoroastrianism, the ancient Persian religion founded by Zarathustra, frames existence as a cosmic struggle between truth (asha) and the lie (druj), with human beings as free moral participants. Its themes of judgement, light and ethical choice influenced later Abrahamic and Gnostic thought.'),
  I('neoplatonism', 'Neoplatonism', '3rd - 6th Century', ['neoplatonism', 'platonism', 'the-one', 'emanation', 'mysticism', 'ancient'], null,
    'Neoplatonism, begun by Plotinus, describes reality as an emanation from the ineffable One through Intellect and Soul down to matter. It shaped Christian, Jewish and Islamic mysticism and metaphysics, and the Renaissance Platonism of Florence.'),

  // ---- Thinkers
  T('al-khwarizmi', 'Muhammad al-Khwarizmi', 'c. 780 - 850 AD', ['khwarezm', 'baghdad', 'islamic', 'mathematics', 'islamic-science', 'algebra', 'persian'], null,
    'Al-Khwarizmi, a scholar of Khwarezm who worked at the House of Wisdom, wrote the Compendious Book on Calculation by Completion and Balancing, from which the word “algebra” comes. His name gave us “algorithm”, and his treatises introduced Hindu-Arabic numerals to the Islamic and European worlds.'),
  T('al-farghani', 'Al-Farghani (Alfraganus)', 'c. 800 - 870 AD', ['fergana', 'baghdad', 'islamic', 'astronomy', 'islamic-science', 'central-asia'], null,
    'Al-Farghani, born in the Fergana Valley, was an astronomer at the Abbasid court whose Elements of Astronomy summarised Ptolemy and measured Earth’s size. Translated into Latin as Alfraganus, his work was read by Dante and Columbus.'),
  T('al-razi', 'Abu Bakr al-Razi (Rhazes)', '854 - 925 AD', ['persia', 'baghdad', 'islamic', 'medicine', 'islamic-science', 'skepticism'], null,
    'Al-Razi was a Persian physician and freethinker who wrote on smallpox, medical ethics and the “five eternals”. He defended philosophy against prophetic authority, making him one of the boldest rationalists in the Islamic tradition.'),
  T('al-bukhari', 'Muhammad al-Bukhari', '810 - 870 AD', ['bukhara', 'islamic', 'hadith', 'jurisprudence', 'uzbekistan', 'central-asia'], null,
    'Al-Bukhari compiled Sahih al-Bukhari, regarded by Sunni Muslims as the most authentic hadith collection, after travelling across the Islamic world to verify narrations. His rigorous criteria for chains of transmission shaped Islamic textual criticism.'),
  T('al-ashari', 'Abu al-Hasan al-Ash‘ari', '874 - 936 AD', ['basra', 'baghdad', 'islamic', 'kalam', 'theology', 'ashari'], null,
    'Al-Ash‘ari broke with the Mu‘tazila and founded the Ash‘ari school of Sunni theology, which upholds divine omnipotence and the reality of God’s attributes. His doctrine of “acquisition” (kasb) tried to reconcile God’s power with human responsibility.'),
  T('al-maturidi', 'Abu Mansur al-Maturidi', 'c. 853 - 944 AD', ['samarkand', 'uzbekistan', 'islamic', 'kalam', 'theology', 'maturidi', 'central-asia'], null,
    'Al-Maturidi of Samarkand founded the Maturidi school of theology, which grants reason a greater role in knowing moral good than the Ash‘ari school. It became the creed of the Hanafi majority and shaped Ottoman, Central Asian and South Asian Islam.'),
  T('ikhwan-al-safa', 'Ikhwan al-Safa (Brethren of Purity)', '10th Century AD', ['basra', 'islamic', 'encyclopedia', 'neoplatonism', 'islamic-philosophy', 'science'], null,
    'The anonymous Brethren of Purity composed the Rasa’il, a 52-treatise encyclopedia of mathematics, natural science, psychology and theology in Basra. They aimed to purify the soul through knowledge, blending Greek, Persian and Indian wisdom with Islamic spirituality.'),
  T('miskawayh', 'Miskawayh', 'c. 932 - 1030 AD', ['persia', 'baghdad', 'islamic', 'ethics', 'virtue', 'history'], null,
    'Miskawayh wrote The Refinement of Character (Tahdhib al-akhlaq), a major Islamic work of virtue ethics combining Aristotle, Plato and Islamic teaching. He saw happiness as the perfecting of the rational soul through education and friendship.'),
  T('al-hallaj', 'Mansur al-Hallaj', 'c. 858 - 922 AD', ['baghdad', 'islamic', 'sufism', 'mysticism', 'persia'], null,
    'Al-Hallaj was a Sufi mystic famed for the ecstatic cry “Ana al-Haqq” (I am the Truth) and executed in Baghdad for it. He became a symbol of mystical love and the tension between inner experience and legal orthodoxy.'),
  T('rabia', 'Rabia al-Adawiyya', 'c. 714 - 801 AD', ['basra', 'islamic', 'sufism', 'mysticism', 'love', 'women-philosophers'], null,
    'Rabia of Basra was an early Sufi saint who taught that God should be loved for His own sake, rather than from fear of hell or hope of paradise. Her pure-love mysticism shaped the whole later Sufi tradition.'),
  T('ibn-al-haytham', 'Ibn al-Haytham (Alhazen)', 'c. 965 - 1040 AD', ['cairo', 'basra', 'islamic', 'optics', 'islamic-science', 'empiricism'], null,
    'Ibn al-Haytham wrote the Book of Optics, showing that vision results from light entering the eye, and advanced an experimental method based on controlled tests. He is often considered a precursor of modern empirical science.'),
  T('al-biruni', 'Al-Biruni', '973 - 1048 AD', ['khwarezm', 'uzbekistan', 'islamic', 'astronomy', 'islamic-science', 'india', 'central-asia'], null,
    'Al-Biruni, a polymath from Khwarezm, measured Earth’s radius, discussed whether Earth rotates and wrote a pioneering study of Indian religion and philosophy after residing in the subcontinent. His comparative method treated other cultures with careful, sympathetic scholarship.'),
  T('omar-khayyam', 'Omar Khayyam', '1048 - 1131 AD', ['nishapur', 'persia', 'islamic', 'mathematics', 'poetry', 'skepticism'], null,
    'Omar Khayyam was a Persian mathematician who solved cubic equations geometrically, reformed the calendar and wrote quatrains (Rubaiyat) meditating on mortality and doubt. He remains a symbol of rational scepticism in Persian culture.'),
  T('ahmad-yasawi', 'Khoja Ahmad Yasawi', 'c. 1093 - 1166 AD', ['turkistan', 'central-asia', 'islamic', 'sufism', 'turkic', 'poetry'], null,
    'Ahmad Yasawi, the Turkic Sufi poet of Turkistan, taught a path of humility and love in his Diwan-i Hikmat, composed in Turkic language. The Yasawi order spread Islam across the steppes, and his mausoleum is a landmark of Central Asia.'),
  T('suhrawardi', 'Shihab al-Din Suhrawardi', '1154 - 1191 AD', ['persia', 'islamic', 'illuminationism', 'ishraq', 'platonism', 'mysticism'], null,
    'Suhrawardi founded the Illuminationist (Ishraq) school, claiming that knowledge by presence and visionary light surpasses purely discursive logic. Executed in Aleppo, he left The Philosophy of Illumination, which shaped Persian philosophy for centuries.'),
  T('ibn-tufayl', 'Ibn Tufayl', 'c. 1105 - 1185 AD', ['cordoba', 'andalusia', 'islamic', 'islamic-philosophy', 'rationalism', 'novel'], null,
    'Ibn Tufayl wrote Hayy ibn Yaqzan, a philosophical novel about a boy raised alone on an island who reaches metaphysical truth through reason and contemplation. It anticipated Robinson Crusoe and debates on natural religion and the tabula rasa.'),
  T('ibn-bajja', 'Ibn Bajja (Avempace)', 'c. 1085 - 1138 AD', ['andalusia', 'islamic', 'islamic-philosophy', 'aristotelianism', 'mind'], null,
    'Ibn Bajja, a philosopher of Zaragoza and Fez, wrote The Regime of the Solitary, arguing that the thinker must pursue intellectual perfection even in a corrupt society. He influenced Ibn Rushd and Albertus Magnus on the intellect and on physics of motion.'),
  T('ibn-arabi', 'Ibn Arabi', '1165 - 1240 AD', ['andalusia', 'damascus', 'islamic', 'sufism', 'metaphysics', 'mysticism'], null,
    'Ibn Arabi, the “Greatest Master”, developed the doctrine of Wahdat al-Wujud, the unity of being, in the Fusus al-Hikam and the Meccan Revelations. His theory of the Perfect Human and the imaginal realm shaped Sufi thought across the Islamic world.'),
  T('nasir-al-din-tusi', 'Nasir al-Din al-Tusi', '1201 - 1274 AD', ['tus', 'persia', 'islamic', 'astronomy', 'ethics', 'islamic-science'], null,
    'Al-Tusi directed the Maragha observatory, devised the Tusi couple (later used by Copernicus), and wrote the Nasirean Ethics. He was a polymath who restored Avicennan philosophy after the Mongol conquests.'),
  T('rumi', 'Jalal al-Din Rumi', '1207 - 1273 AD', ['konya', 'persia', 'islamic', 'sufism', 'poetry', 'love', 'mevlevi'], null,
    'Rumi, a Persian poet born in Balkh and settled in Konya, composed the Masnavi, a vast spiritual epic of love and longing for the Divine. His teaching inspired the Mevlevi order and made him the best-selling poet of the modern world.'),
  T('hafez', 'Hafez of Shiraz', 'c. 1325 - 1390 AD', ['shiraz', 'persia', 'islamic', 'sufism', 'poetry', 'love'], null,
    'Hafez, master of the ghazal, merged earthly and mystical love, mocked hypocritical piety and treated wine, beloved and tavern as symbols of spiritual intoxication. His Divan remains a cornerstone of Persian cultural identity.'),
  T('naqshband', 'Bahauddin Naqshband', '1318 - 1389 AD', ['bukhara', 'uzbekistan', 'islamic', 'sufism', 'central-asia', 'naqshbandi'], null,
    'Bahauddin Naqshband of Bukhara founded the Naqshbandi order, which stresses silent remembrance (dhikr), sobriety and engagement in worldly life: “the heart to God, the hand at work”. The order spread across Central Asia, Anatolia and India.'),
  T('ulugh-beg', 'Ulugh Beg', '1394 - 1449 AD', ['samarkand', 'uzbekistan', 'islamic', 'astronomy', 'timurid', 'central-asia', 'islamic-science'], null,
    'Ulugh Beg, grandson of Timur and ruler of Samarkand, built a great observatory and compiled the Zij-i Sultani, a star catalogue of unprecedented accuracy. A scholar-prince, he made Samarkand a centre of mathematics and astronomy.'),
  T('ibn-taymiyya', 'Ibn Taymiyya', '1263 - 1328 AD', ['damascus', 'islamic', 'theology', 'jurisprudence', 'salafi', 'logic'], null,
    'Ibn Taymiyya, a Hanbali jurist of Damascus, attacked Greek logic and Sufi excesses, calling for a return to the Qur’an and Sunna. His thought deeply influences later reformist and revivalist movements and he also wrote sharp critiques of Aristotelian syllogisms.'),
  T('navoi', 'Alisher Navoi', '1441 - 1501 AD', ['herat', 'uzbekistan', 'central-asia', 'islamic', 'poetry', 'turkic', 'sufism'], null,
    'Alisher Navoi, poet-statesman of Timurid Herat, defended Chagatai Turkic as a literary language equal to Persian in works like Muhakamat al-Lughatayn and the Khamsa. He is the founding figure of Uzbek literature and a humanist of Sufi inspiration.'),
  T('mulla-sadra', 'Mulla Sadra', 'c. 1571 - 1640 AD', ['isfahan', 'shiraz', 'persia', 'islamic', 'transcendent-theosophy', 'metaphysics'], null,
    'Mulla Sadra founded Transcendent Theosophy in The Four Journeys, arguing the primacy of existence over essence and the substantial motion of all things. He synthesised philosophy, illumination and Sufi gnosis into the dominant school of later Iranian thought.'),
  T('shah-waliullah', 'Shah Waliullah Dehlawi', '1703 - 1762 AD', ['delhi', 'india', 'islamic', 'reform', 'theology', 'sufism'], null,
    'Shah Waliullah of Delhi sought to reconcile Sufi metaphysics and jurisprudence in Hujjat Allah al-Baligha, analysing the social reasons behind Islamic law. He responded to Mughal decline with a program of intellectual and moral revival.'),
  T('al-afghani', 'Jamal al-Din al-Afghani', '1838 - 1897 AD', ['cairo', 'persia', 'islamic', 'islamic-modernism', 'politics', 'reform'], null,
    'Al-Afghani, a roving political thinker, urged Muslim unity against colonialism and the revival of reasoned scholarship. He is regarded as a founder of Islamic modernism and pan-Islamic political thought.'),
  T('abduh', 'Muhammad Abduh', '1849 - 1905 AD', ['cairo', 'egypt', 'islamic', 'islamic-modernism', 'reform', 'education'], null,
    'Muhammad Abduh, Grand Mufti of Egypt, reformed al-Azhar and argued that Islam is compatible with reason, science and educational progress. His Theology of Unity and his disciples shaped modernist currents across the Arab world.'),
  T('behbudi', 'Mahmudkhoja Behbudi', '1875 - 1919 AD', ['samarkand', 'bukhara', 'uzbekistan', 'jadidism', 'central-asia', 'education', 'islamic'], null,
    'Behbudi, the leading Jadid of Turkestan, founded new-method schools, wrote the first Uzbek play and edited the newspaper Oyna. He argued that national survival depends on modern education, science and civic life.'),
  T('fitrat', 'Abdurauf Fitrat', '1886 - 1938 AD', ['bukhara', 'uzbekistan', 'jadidism', 'central-asia', 'literature', 'islamic'], null,
    'Fitrat, a Bukharan Jadid writer, philologist and dramatist, championed cultural renewal, linguistic reform and a modern Uzbek identity. He was executed in Stalin’s purges of 1938, but his works remain central to Uzbek intellectual history.'),
  T('iqbal', 'Muhammad Iqbal', '1877 - 1938 AD', ['lahore', 'islamic', 'islamic-modernism', 'poetry', 'selfhood', 'persian', 'pakistan'], null,
    'Muhammad Iqbal, poet-philosopher of Lahore, wrote The Reconstruction of Religious Thought in Islam and a philosophy of dynamic selfhood (khudi). Drawing on Bergson, Nietzsche and Rumi, he called Muslims to creative ijtihad and self-realisation.'),
  T('shariati', 'Ali Shariati', '1933 - 1977 AD', ['persia', 'tehran', 'islamic', 'sociology', 'politics', 'existentialism'], null,
    'Ali Shariati, Iranian sociologist trained in Paris, reinterpreted Shi‘i Islam as a philosophy of liberation, drawing on Fanon, Sartre and Massignon. His lectures profoundly influenced the intellectual climate before the 1979 Iranian revolution.'),
  T('fazlur-rahman', 'Fazlur Rahman', '1919 - 1988 AD', ['lahore', 'chicago', 'islamic', 'islamic-modernism', 'hermeneutics', 'reform'], null,
    'Fazlur Rahman proposed a “double movement” method of interpreting the Qur’an, moving from its historical context to present ethical principles. He taught at Chicago and defended systematic Islamic reform grounded in scholarship.'),
  T('nasr', 'Seyyed Hossein Nasr', '1933 - Present', ['persia', 'tehran', 'islamic', 'sufism', 'perennialism', 'ecology'], null,
    'Seyyed Hossein Nasr is a Persian philosopher of religion who writes on Islamic science, Sufism and the sacred in nature, offering a traditionalist critique of modern secularism. His works helped introduce Islamic philosophy to Western readers.'),
  T('al-jabri', 'Mohammed Abed al-Jabri', '1935 - 2010 AD', ['fez', 'morocco', 'islamic', 'epistemology', 'critique', 'reason'], null,
    'Al-Jabri, a Moroccan philosopher, wrote the Critique of Arab Reason, distinguishing the explanatory (bayani), gnostic (irfani) and demonstrative (burhani) epistemic systems in Islamic thought. He argued for recovering the rationalism of Ibn Rushd and Ibn Khaldun.'),
  T('soroush', 'Abdolkarim Soroush', '1945 - Present', ['persia', 'tehran', 'islamic', 'islamic-modernism', 'epistemology', 'hermeneutics'], null,
    'Abdolkarim Soroush is an Iranian philosopher who distinguishes religion from religious knowledge, arguing the latter is human, historical and revisable. His work supports democratic pluralism within Islam.')
);

