// ---------------------------------------------------------------------
//  PART B — Futurology, technology, AI, mind, ethics of the future
// ---------------------------------------------------------------------
NODES.push(
  // ---- Ideas
  I('futurology', 'Futurology & Foresight', '20th - 21st Century', ['futurology', 'futurism', 'forecasting', 'technology', 'foresight', 'future'], null,
    'Futurology is the systematic study of possible, probable and preferable futures, from H.G. Wells’s call for a “science of foresight” to scenario planning and technology forecasting. It asks how scientific, economic and cultural trends shape society, and how far prediction is possible at all.'),
  I('transhumanism', 'Transhumanism & Human Enhancement', 'Late 20th - 21st Century', ['transhumanism', 'futurism', 'enhancement', 'technology', 'ethics', 'future'], null,
    'Transhumanism holds that humanity can and should use technology to overcome biological limits on lifespan, intelligence and well-being. Critics such as Habermas and Sandel worry about equality, authenticity and what it means to be human.'),
  I('singularity', 'The Technological Singularity', 'Late 20th - 21st Century', ['singularity', 'futurism', 'ai', 'technology', 'intelligence-explosion', 'future'], null,
    'The Singularity hypothesis, from I.J. Good’s “intelligence explosion” to Vernor Vinge and Ray Kurzweil, posits that self-improving machine intelligence could rapidly surpass human intelligence. It remains controversial, split between enthusiasts, sceptics and those who see it as a risk to be managed.'),
  I('ai-safety', 'AI Safety & Alignment', '21st Century', ['ai-safety', 'ai', 'alignment', 'ethics', 'technology', 'future', 'existential-risk'], null,
    'AI safety studies how to ensure that advanced AI systems act in accordance with human values and interests. It spans technical alignment research, governance, and philosophical questions about value, control and moral status of machines.'),
  I('philosophy-of-ai', 'Philosophy of Artificial Intelligence', '20th - 21st Century', ['ai', 'philosophy-of-ai', 'mind', 'computation', 'consciousness', 'technology'], null,
    'The philosophy of AI asks whether machines can think, understand or be conscious. From Turing’s imitation game to Searle’s Chinese Room and debates about large language models, it tests theories of mind against engineered systems.'),
  I('existential-risk', 'Existential Risk & Longtermism', '21st Century', ['existential-risk', 'longtermism', 'ethics', 'future', 'effective-altruism', 'futurism'], null,
    'Existential-risk studies argue that threats to humanity’s long-term potential, such as engineered pandemics or unaligned AI, deserve extraordinary priority. Longtermism extends moral concern to future generations, drawing on Parfit’s population ethics.'),
  I('cybernetics', 'Cybernetics & Systems Theory', '1940s - Present', ['cybernetics', 'systems', 'technology', 'information', 'control', 'future'], null,
    'Cybernetics, founded by Norbert Wiener, studies feedback, communication and control in animals, machines and societies. It inspired systems theory, cognitive science, ecology and early visions of human-machine symbiosis.'),
  I('posthumanism', 'Posthumanism & Cyborg Theory', 'Late 20th - 21st Century', ['posthumanism', 'cyborg', 'feminism', 'technology', 'postmodernism', 'future'], null,
    'Posthumanism questions the human as the measure of all things, stressing entanglements of humans, animals, machines and environments. Haraway’s Cyborg Manifesto and Latour’s actor-network theory dissolve borders between nature, society and technology.'),
  I('philosophy-of-technology', 'Philosophy of Technology', '19th - 21st Century', ['philosophy-of-technology', 'technology', 'modernism', 'critique', 'ethics', 'media'], null,
    'The philosophy of technology investigates how tools and systems shape human life, from Heidegger’s “enframing” to Ellul’s technological society and Simondon’s individuation. It asks whether technology is neutral or reshapes our values and freedom.'),
  I('technological-determinism', 'Technological Determinism & Media Theory', '20th Century', ['media', 'technology', 'mcluhan', 'communication', 'determinism'], null,
    'Technological determinism claims that technologies drive social change. McLuhan’s “the medium is the message” argued that communication media reshape perception and society, whatever their content.'),
  I('cosmism', 'Russian Cosmism', 'Late 19th - 20th Century', ['cosmism', 'russia', 'russian', 'futurism', 'space', 'immortality', 'orthodox'], null,
    'Russian Cosmism, from Nikolai Fedorov to Tsiolkovsky and Vernadsky, envisioned humanity’s duty to conquer death, colonise space and steward the biosphere. It fused Orthodox eschatology with science and anticipated transhumanism and space exploration.'),
  I('effective-altruism', 'Effective Altruism', '21st Century', ['effective-altruism', 'utilitarianism', 'ethics', 'charity', 'longtermism', 'future'], null,
    'Effective altruism applies evidence and reason to do the most good, from global health to animal welfare and existential risk. Critics question its utilitarian assumptions, measurement problems and political naïveté.'),
  I('digital-society', 'Digital Society & Surveillance Capitalism', '21st Century', ['digital', 'surveillance', 'technology', 'critique', 'capitalism', 'media', 'future'], null,
    'Scholars of the digital society analyse how platforms, data extraction and algorithmic governance reshape power, attention and freedom. Zuboff’s surveillance capitalism and Han’s “psychopolitics” diagnose new forms of control.'),
  I('political-economy', 'Political Economy & Economic Thought', '18th - 21st Century', ['economics', 'political-economy', 'capitalism', 'markets', 'politics', 'economy'], null,
    'Political economy examines how markets, states and institutions distribute wealth and power. From Smith and Ricardo to Marx, Keynes, Hayek, Polanyi and Sen, it is the field where philosophy meets economics.'),
  I('ecology-ethics', 'Environmental Philosophy', '20th - 21st Century', ['ecology', 'environment', 'ethics', 'future', 'sustainability', 'nature'], null,
    'Environmental philosophy asks about our obligations to nature and future generations, from Aldo Leopold’s land ethic to Hans Jonas’s imperative of responsibility and deep ecology. It is increasingly central to debates over climate and technology.'),

  // ---- Thinkers
  T('hg-wells', 'H.G. Wells', '1866 - 1946 AD', ['london', 'futurology', 'futurism', 'literature', 'science-fiction', 'british'], null,
    'H.G. Wells, science-fiction pioneer, called in 1902 for a “science of the future” and wrote The Time Machine and A Modern Utopia. He campaigned for world government and universal education, and helped found modern futures studies.'),
  T('wiener', 'Norbert Wiener', '1894 - 1964 AD', ['boston', 'cybernetics', 'technology', 'ethics', 'american', 'systems'], null,
    'Norbert Wiener, MIT mathematician, founded cybernetics and warned in The Human Use of Human Beings that automation could dehumanise work and society. He argued scientists must take moral responsibility for their inventions.'),
  T('turing', 'Alan Turing', '1912 - 1954 AD', ['oxford-cambridge', 'logic', 'ai', 'philosophy-of-ai', 'computation', 'british', 'mind'], null,
    'Alan Turing formalised computation with the Turing machine and proposed the imitation game as a test of machine intelligence. His 1950 paper “Computing Machinery and Intelligence” launched the philosophy of artificial intelligence.'),
  T('von-neumann', 'John von Neumann', '1903 - 1957 AD', ['computation', 'mathematics', 'game-theory', 'technology', 'american', 'singularity'], null,
    'John von Neumann, polymath of game theory, quantum mechanics and computer architecture, was reported to have spoken of an “essential singularity” in human history due to accelerating technology. He also developed the theory of self-reproducing automata.'),
  T('good', 'I.J. Good', '1916 - 2009 AD', ['oxford-cambridge', 'ai', 'singularity', 'intelligence-explosion', 'statistics', 'british'], null,
    'I.J. Good, Bletchley Park cryptanalyst, wrote in 1965 of an “ultraintelligent machine” that could design better machines, calling it “the last invention that man need ever make”. His idea of an intelligence explosion underlies modern AI-risk discussions.'),
  T('fuller', 'Buckminster Fuller', '1895 - 1983 AD', ['futurology', 'design', 'technology', 'sustainability', 'american', 'systems'], null,
    'Buckminster Fuller, designer and systems thinker, coined “Spaceship Earth” and promoted comprehensive anticipatory design to achieve abundance with minimal resources. He is a founding figure of sustainability and futures thinking.'),
  T('mcluhan', 'Marshall McLuhan', '1911 - 1980 AD', ['media', 'technological-determinism', 'technology', 'canadian', 'communication', 'futurism'], null,
    'Marshall McLuhan, Canadian media theorist, argued in Understanding Media that “the medium is the message” and imagined a “global village” created by electronic media. His ideas anticipated the internet age.'),
  T('toffler', 'Alvin Toffler', '1928 - 2016 AD', ['futurology', 'futurism', 'technology', 'society', 'american', 'forecasting'], null,
    'Alvin Toffler popularised futurology in Future Shock and The Third Wave, diagnosing the stress of accelerating change and the shift from industrial to information society. His work made forecasting a mainstream public discourse.'),
  T('kurzweil', 'Ray Kurzweil', '1948 - Present', ['silicon-valley', 'singularity', 'futurism', 'transhumanism', 'ai', 'american'], null,
    'Ray Kurzweil, inventor and futurist, predicts in The Singularity Is Near that exponential growth in computing will merge humans and machines by mid-century. He is a leading proponent of optimistic, transhumanist futurism.'),
  T('vinge', 'Vernor Vinge', '1944 - 2024 AD', ['singularity', 'futurism', 'ai', 'science-fiction', 'american', 'technology'], null,
    'Vernor Vinge, mathematician and novelist, popularised “the Singularity” in a 1993 essay predicting superhuman intelligence within decades. His fiction explored the limits of human understanding in a post-Singularity world.'),
  T('moravec', 'Hans Moravec', '1948 - Present', ['ai', 'robotics', 'futurism', 'transhumanism', 'mind', 'computation'], null,
    'Hans Moravec, robotics pioneer, noted that tasks easy for humans are hard for machines (Moravec’s paradox) and speculated about mind uploading in Mind Children. He helped shape transhumanist visions of post-biological intelligence.'),
  T('bostrom', 'Nick Bostrom', '1973 - Present', ['oxford-cambridge', 'existential-risk', 'ai-safety', 'transhumanism', 'ethics', 'future', 'swedish'], null,
    'Nick Bostrom, Oxford philosopher, wrote Superintelligence on the control problem for advanced AI, formulated the simulation argument and the vulnerable world hypothesis. He is a leading figure in existential-risk studies.'),
  T('parfit', 'Derek Parfit', '1942 - 2017 AD', ['oxford-cambridge', 'ethics', 'personal-identity', 'future', 'utilitarianism', 'british'], null,
    'Derek Parfit’s Reasons and Persons revolutionised personal identity and population ethics, including the “Repugnant Conclusion”. His work underlies longtermist moral concern for future generations.'),
  T('singer', 'Peter Singer', '1946 - Present', ['utilitarianism', 'ethics', 'effective-altruism', 'animal-rights', 'australian', 'future'], null,
    'Peter Singer, utilitarian ethicist, argued in Animal Liberation and “Famine, Affluence, and Morality” that suffering anywhere deserves equal moral concern. His work provided the intellectual foundation for effective altruism.'),
  T('ord', 'Toby Ord', '1979 - Present', ['oxford-cambridge', 'existential-risk', 'effective-altruism', 'ethics', 'future', 'longtermism'], null,
    'Toby Ord, Oxford philosopher, co-founded Giving What We Can and wrote The Precipice, estimating the probabilities of existential catastrophe this century. He argues that safeguarding humanity’s future is a defining moral priority.'),
  T('yudkowsky', 'Eliezer Yudkowsky', '1979 - Present', ['silicon-valley', 'ai-safety', 'rationality', 'singularity', 'american', 'future'], null,
    'Eliezer Yudkowsky, co-founder of the Machine Intelligence Research Institute, was among the first to argue that aligning superintelligent AI is a hard technical problem. He also built the “rationalist” community around Bayesian reasoning.'),
  T('russell-stuart', 'Stuart Russell', '1962 - Present', ['ai-safety', 'ai', 'alignment', 'silicon-valley', 'british', 'future'], null,
    'Stuart Russell, co-author of the leading AI textbook, argued in Human Compatible that machines should be built to be uncertain about human preferences. His “assistance game” approach is a major research direction in alignment.'),
  T('tegmark', 'Max Tegmark', '1967 - Present', ['ai-safety', 'physics', 'future', 'swedish', 'consciousness', 'futurism'], null,
    'Max Tegmark, physicist and co-founder of the Future of Life Institute, wrote Life 3.0 on AI’s consequences and proposed the Mathematical Universe Hypothesis. He champions public debate on AI governance.'),
  T('harari', 'Yuval Noah Harari', '1976 - Present', ['jerusalem', 'history', 'futurology', 'technology', 'israeli', 'future'], null,
    'Yuval Noah Harari, historian, wrote Sapiens, Homo Deus and 21 Lessons, linking human cooperation, shared fictions and emerging biotechnology and AI to potential futures. He warns about data-driven authoritarianism and the end of humanism.'),
  T('haraway', 'Donna Haraway', '1944 - Present', ['posthumanism', 'cyborg', 'feminism', 'american', 'technology', 'boston-harvard'], null,
    'Donna Haraway’s “A Cyborg Manifesto” (1985) rejected rigid boundaries between human, animal and machine and championed partial perspectives. Later works on companion species and “making kin” shaped posthumanist environmental thought.'),
  T('latour', 'Bruno Latour', '1947 - 2022 AD', ['paris', 'posthumanism', 'science-studies', 'technology', 'french', 'ecology'], null,
    'Bruno Latour developed actor-network theory, which treats humans and non-humans as co-actors in networks. In We Have Never Been Modern and later works on climate, he argued that the nature–society divide is a modern illusion.'),
  T('ellul', 'Jacques Ellul', '1912 - 1994 AD', ['bordeaux', 'philosophy-of-technology', 'technology', 'critique', 'french', 'christian-anarchism'], null,
    'Jacques Ellul argued in The Technological Society that “technique” follows an autonomous logic of efficiency that subordinates human values. A Christian anarchist, he also wrote about propaganda and freedom.'),
  T('mumford', 'Lewis Mumford', '1895 - 1990 AD', ['philosophy-of-technology', 'technology', 'cities', 'critique', 'american', 'history'], null,
    'Lewis Mumford’s Technics and Civilization traced the long entanglement of machines, cities and culture, warning of the “megamachine” of centralised power. He called for humane technology scaled to human needs.'),
  T('simondon', 'Gilbert Simondon', '1924 - 1989 AD', ['paris', 'philosophy-of-technology', 'individuation', 'technology', 'french', 'cybernetics'], null,
    'Gilbert Simondon wrote On the Mode of Existence of Technical Objects, arguing that technical objects individuate through “concretisation” and deserve cultural recognition. He influenced Deleuze and contemporary philosophy of technology.'),
  T('stiegler', 'Bernard Stiegler', '1952 - 2020 AD', ['paris', 'philosophy-of-technology', 'digital', 'critique', 'french', 'media'], null,
    'Bernard Stiegler analysed technology as pharmakon, both poison and cure, and argued digital capitalism short-circuits attention and long-term thinking. He called for a new politics of care and “neganthropy”.'),
  T('arendt', 'Hannah Arendt', '1906 - 1975 AD', ['berlin', 'paris', 'politics', 'phenomenology', 'german', 'totalitarianism', 'ethics'], null,
    'Hannah Arendt, a student of Heidegger and Jaspers, analysed totalitarianism, the “banality of evil” and the human capacity for natality in The Human Condition. Her work on action and plurality remains central to political philosophy.'),
  T('marcuse', 'Herbert Marcuse', '1898 - 1979 AD', ['frankfurt', 'critical-theory', 'marxism', 'technology', 'german', 'politics'], null,
    'Herbert Marcuse’s One-Dimensional Man argued that advanced industrial society integrates opposition through consumerism and technological rationality. He became an intellectual hero of the 1960s New Left.'),
  T('jonas', 'Hans Jonas', '1903 - 1993 AD', ['heidelberg', 'ethics', 'ecology', 'philosophy-of-technology', 'german', 'future'], null,
    'Hans Jonas’s The Imperative of Responsibility proposed an ethics for the technological age, demanding that we act so that the effects of our actions are compatible with the permanence of genuine human life. It is a cornerstone of environmental and bioethics.'),
  T('anders', 'Günther Anders', '1902 - 1992 AD', ['philosophy-of-technology', 'technology', 'critique', 'german', 'nuclear', 'ethics'], null,
    'Günther Anders, Arendt’s first husband, wrote The Obsolescence of Man, arguing humans lag behind their technological creations, a “Promethean gap”. His reflections on the atom bomb and mass media remain provocative.'),
  T('byung-chul-han', 'Byung-Chul Han', '1959 - Present', ['berlin', 'digital', 'critique', 'philosophy-of-technology', 'korean', 'german'], null,
    'Byung-Chul Han, Korean-German philosopher, diagnoses the burnout society and “psychopolitics” in which self-exploitation and transparency replace overt discipline. His short, aphoristic books critique digital capitalism and the loss of rituals and rest.'),
  T('zuboff', 'Shoshana Zuboff', '1951 - Present', ['boston-harvard', 'digital', 'surveillance', 'capitalism', 'american', 'future'], null,
    'Shoshana Zuboff, Harvard scholar, coined “surveillance capitalism” to describe the economic order that extracts behavioural data to predict and modify human conduct. She argues for democratic limits on this new power.'),
  T('searle', 'John Searle', '1932 - 2025 AD', ['oxford-cambridge', 'mind', 'philosophy-of-ai', 'language', 'american', 'consciousness'], null,
    'John Searle’s Chinese Room argument (1980) claims that symbol manipulation alone cannot give understanding, challenging strong AI. He also developed speech-act theory and a theory of social reality.'),
  T('dennett', 'Daniel Dennett', '1942 - 2024 AD', ['boston-harvard', 'mind', 'philosophy-of-ai', 'consciousness', 'american', 'materialism'], null,
    'Daniel Dennett defended a naturalistic, functionalist account of consciousness, arguing that the “hard problem” is illusory, in Consciousness Explained. He also championed evolutionary thinking and the intentional stance.'),
  T('dreyfus', 'Hubert Dreyfus', '1929 - 2017 AD', ['berkeley', 'phenomenology', 'philosophy-of-ai', 'heidegger', 'american', 'mind'], null,
    'Hubert Dreyfus used Heidegger and Merleau-Ponty to criticise symbolic AI in What Computers Can’t Do, arguing that human expertise relies on embodied, tacit skill. His critique anticipated later turns to embodied cognition.'),
  T('clark', 'Andy Clark', '1957 - Present', ['mind', 'cognitive-science', 'philosophy-of-ai', 'edinburgh', 'british', 'posthumanism'], null,
    'Andy Clark and David Chalmers proposed the “extended mind” thesis, according to which tools such as notebooks and smartphones can be literally part of cognition. Clark’s “natural-born cyborgs” portrays humans as intrinsically technological.'),
  T('kuhn', 'Thomas Kuhn', '1922 - 1996 AD', ['boston-harvard', 'science', 'epistemology', 'history', 'american', 'paradigm'], null,
    'Thomas Kuhn’s The Structure of Scientific Revolutions introduced “paradigms” and “normal science”, showing that science advances through periodic revolutions rather than steady accumulation. His book reshaped the philosophy and sociology of science.'),
  T('keynes', 'John Maynard Keynes', '1883 - 1946 AD', ['oxford-cambridge', 'economics', 'political-economy', 'british', 'future', 'politics'], null,
    'John Maynard Keynes, Cambridge economist, argued in The General Theory that aggregate demand drives employment and that governments should stabilise the business cycle. His essay “Economic Possibilities for our Grandchildren” predicted a 15-hour work week by 2030.'),
  T('hayek', 'Friedrich Hayek', '1899 - 1992 AD', ['vienna', 'london', 'economics', 'political-economy', 'austrian', 'liberty'], null,
    'Friedrich Hayek, Austrian economist, argued that dispersed knowledge makes central planning impossible and that spontaneous order in markets coordinates society. His The Road to Serfdom and The Constitution of Liberty shaped modern classical liberalism.'),
  T('polanyi', 'Karl Polanyi', '1886 - 1964 AD', ['vienna', 'london', 'economics', 'political-economy', 'hungarian', 'critique'], null,
    'Karl Polanyi argued in The Great Transformation that the self-regulating market is a historical anomaly that disembeds the economy from society. His “double movement” predicts social protection against market forces.'),
  T('schumpeter', 'Joseph Schumpeter', '1883 - 1950 AD', ['vienna', 'boston-harvard', 'economics', 'political-economy', 'austrian', 'innovation'], null,
    'Joseph Schumpeter coined “creative destruction” to describe capitalism’s innovation-driven evolution and the role of the entrepreneur. He doubted capitalism’s long-term survival, foreseeing it would erode its own social supports.'),
  T('ricardo', 'David Ricardo', '1772 - 1823 AD', ['london', 'economics', 'political-economy', 'british', 'trade', 'classical-economics'], null,
    'David Ricardo’s Principles of Political Economy and Taxation set out comparative advantage, the case for free trade, and the labour theory of value. His analysis of rent and distribution framed classical economics.'),
  T('weber', 'Max Weber', '1864 - 1920 AD', ['heidelberg', 'berlin', 'sociology', 'economics', 'german', 'politics', 'modernism'], null,
    'Max Weber linked the Protestant ethic to the spirit of capitalism and analysed bureaucracy as the “iron cage” of modern rationalisation. His definitions of the state and legitimate authority remain standard in the social sciences.'),
  T('sen', 'Amartya Sen', '1933 - Present', ['oxford-cambridge', 'boston-harvard', 'economics', 'justice', 'indian', 'development', 'ethics'], null,
    'Amartya Sen, Nobel laureate, reframed development as expanding human capabilities and freedoms, and showed that famines result from entitlement failures rather than food shortages. His The Idea of Justice challenges Rawlsian idealism with comparative approaches.'),
  T('veblen', 'Thorstein Veblen', '1857 - 1929 AD', ['chicago', 'economics', 'sociology', 'american', 'critique', 'institutional-economics'], null,
    'Thorstein Veblen’s The Theory of the Leisure Class introduced “conspicuous consumption” and critiqued business culture from an evolutionary, institutional perspective. He founded institutional economics.'),
  T('leopold', 'Aldo Leopold', '1887 - 1948 AD', ['ecology', 'environment', 'ethics', 'american', 'land-ethic', 'sustainability'], null,
    'Aldo Leopold, forester and ecologist, articulated the “land ethic” in A Sand County Almanac, extending moral community to soils, waters and animals. It is a founding text of environmental ethics.'),
  T('naess', 'Arne Næss', '1912 - 2009 AD', ['ecology', 'environment', 'ethics', 'norwegian', 'deep-ecology', 'sustainability'], null,
    'Arne Næss, Norwegian philosopher, coined “deep ecology”, which holds that all living beings have intrinsic value regardless of their use to humans. He drew on Spinoza, Gandhi and Buddhism.')
);

