NODES.push(
  // ---- Ideas
  I('orthodox-theology', 'Eastern Orthodox Theology & Hesychasm', 'Byzantine Era to Present', ['orthodox', 'byzantium', 'theology', 'hesychasm', 'mysticism', 'apophatic'], null,
    'Eastern Orthodox theology stresses theosis, the participation of humans in divine life, and apophatic knowledge of God beyond concepts. Hesychasm, defended by Gregory Palamas, teaches contemplative prayer in which the uncreated divine energies are experienced.'),
  I('russian-religious-philosophy', 'Russian Religious Philosophy', '19th - 20th Century', ['russia', 'russian', 'orthodox', 'philosophy', 'slavophiles', 'sophiology', 'silver-age'], null,
    'Russian religious philosophy, from the Slavophiles to Solovyov, Berdyaev and Florensky, sought a holistic knowledge uniting faith, reason and community (sobornost). It debated Russia’s destiny and criticised Western rationalism and individualism.'),
  I('slavophiles-westernizers', 'Slavophiles vs Westernizers', '1830s - 1860s', ['russia', 'russian', 'politics', 'slavophiles', 'westernizers', 'debate'], null,
    'The Slavophile–Westernizer debate asked whether Russia should follow Europe or develop from its own Orthodox and communal roots. Chaadaev’s Philosophical Letters triggered the controversy, which shaped Russian political thought.'),
  I('byzantine-platonism', 'Byzantine Humanism & Platonism', '9th - 15th Century', ['byzantium', 'platonism', 'humanism', 'greek', 'renaissance', 'constantinople'], null,
    'Byzantine scholars preserved, copied and commented on Plato, Aristotle and the Neoplatonists, from Photius to Psellos and Plethon. Their migration to Italy after 1453 helped ignite the Renaissance Platonic revival.'),
  I('mysticism-west', 'Western Mysticism & Negative Theology', '12th - 15th Century', ['mysticism', 'apophatic', 'medieval', 'neoplatonism', 'theology', 'german'], null,
    'Medieval Western mystics such as Hildegard, Meister Eckhart and Nicholas of Cusa explored the soul’s union with the ineffable God. Drawing on Pseudo-Dionysius and Neoplatonism, they used paradox and “learned ignorance” to speak of the unspeakable.'),
  I('scientific-revolution', 'The Scientific Revolution', '16th - 17th Century', ['science', 'scientific-revolution', 'astronomy', 'empiricism', 'mathematics', 'renaissance'], null,
    'The Scientific Revolution, from Copernicus and Galileo to Newton, replaced Aristotelian cosmology with a mathematical, experimental science of nature. It reshaped philosophy, prompting Descartes, Bacon and Leibniz to rethink knowledge and method.'),
  I('natural-law', 'Natural Law & Human Rights', 'Antiquity to Modern', ['natural-law', 'rights', 'law', 'ethics', 'stoicism', 'politics', 'human-rights'], null,
    'Natural-law theory holds that universal moral principles accessible to reason ground positive law, from Cicero and Aquinas to Grotius and modern human-rights doctrine. Salamancan jurists applied it to conquest and international relations.'),
  I('romanticism', 'Romanticism', 'Late 18th - 19th Century', ['romanticism', 'nature', 'german', 'literature', 'feeling', 'idealism'], null,
    'Romanticism prized feeling, imagination, nature and the individual genius against Enlightenment rationalism. From Rousseau and Herder to Goethe, Schelling and Coleridge, it reshaped art, politics and philosophy.'),
  I('positivism', 'Positivism & Sociology', '19th Century', ['positivism', 'sociology', 'science', 'comte', 'durkheim', 'french'], null,
    'Positivism, founded by Auguste Comte, holds that genuine knowledge comes from scientific observation and that society can be studied scientifically. It gave birth to sociology and influenced Mill, Durkheim and the Vienna Circle.'),
  I('anarchism', 'Anarchism & Libertarian Socialism', '19th - 20th Century', ['anarchism', 'politics', 'liberty', 'socialism', 'russian', 'french'], null,
    'Anarchism rejects coercive hierarchy and the state, defending voluntary association and mutual aid. Thinkers such as Proudhon, Bakunin and Kropotkin imagined societies based on solidarity and decentralisation.'),
  I('marxism', 'Marxism & Socialist Thought', '19th - 21st Century', ['marxism', 'socialism', 'politics', 'materialism', 'capitalism', 'critique'], null,
    'Marxism analyses history through class struggle and the material conditions of production, and aims at a classless society. Its variants include Lenin’s vanguard theory, Gramsci’s hegemony, and the Frankfurt School’s critical theory.'),
  I('psychoanalysis', 'Psychoanalysis & Depth Psychology', 'Late 19th - 20th Century', ['psychoanalysis', 'vienna', 'mind', 'unconscious', 'psychology', 'modernism'], null,
    'Psychoanalysis, founded by Freud in Vienna, argued that unconscious drives, repression and childhood experience shape the mind. It influenced philosophy, literature and critical theory, from Jung and Lacan to the Frankfurt School.'),
  I('sociology-classic', 'Classical Sociology', 'Late 19th - Early 20th Century', ['sociology', 'durkheim', 'weber', 'simmel', 'modernism', 'society'], null,
    'Classical sociology, from Durkheim’s social facts to Weber’s interpretive method and Simmel’s forms of sociation, analysed the transformations of modernity. It studied division of labour, bureaucracy, religion and urban life.'),
  I('liberation-philosophy', 'Liberation Philosophy & Pedagogy', '20th Century', ['liberation', 'latin-america', 'education', 'decolonial', 'marxism', 'theology'], null,
    'Liberation thinkers, including Freire and Dussel, hold that philosophy must side with the oppressed and that education should foster critical consciousness. Liberation theology joined Christian faith to social justice in Latin America.'),
  I('postcolonial', 'Postcolonial & Decolonial Thought', '20th - 21st Century', ['postcolonial', 'decolonial', 'critique', 'politics', 'africa', 'identity'], null,
    'Postcolonial theory examines the legacy of empire in knowledge, culture and identity, from Fanon’s psychology of colonialism to Said’s Orientalism and Spivak’s subaltern. Decolonial thinkers demand that philosophy recognise non-Western epistemologies.'),
  I('african-philosophy', 'Ubuntu & African Philosophy', 'Oral Tradition to Present', ['ubuntu', 'africa', 'african', 'communitarianism', 'ethics', 'personhood'], null,
    'Ubuntu, summarised as “I am because we are”, holds that personhood is realised through relationships and community. African philosophy also includes Akan metaphysics, Yoruba epistemology and critiques of colonial knowledge.'),
  I('neo-confucianism', 'Neo-Confucianism', '11th - 17th Century', ['neo-confucianism', 'china', 'confucianism', 'metaphysics', 'li-qi', 'chinese'], null,
    'Neo-Confucianism reformulated Confucian ethics with a metaphysics of principle (li) and vital energy (qi), absorbing Buddhist and Daoist influences. Zhu Xi’s rationalist school and Wang Yangming’s “mind-learning” dominated East Asian thought.'),
  I('jainism', 'Jainism & Ahimsa', '6th Century BC - Present', ['jainism', 'india', 'ahimsa', 'ethics', 'indian', 'anekantavada', 'ascetic'], null,
    'Jainism, taught by Mahavira, centres on ahimsa (non-violence), asceticism and anekantavada, the doctrine that reality is many-sided. Its perspectival logic anticipates modern pluralism and its ethics of non-harm inspired Gandhi.'),
  I('samkhya-yoga', 'Samkhya & Yoga Philosophy', 'c. 500 BC - 400 AD', ['samkhya', 'yoga', 'india', 'indian', 'dualism', 'meditation', 'consciousness'], null,
    'Samkhya posits a dualism of pure consciousness (purusha) and matter (prakriti), while Patanjali’s Yoga Sutras provide a discipline for stilling the mind. Together they offer an ancient Indian analysis of consciousness and liberation.'),
  I('nyaya-pramana', 'Nyaya, Pramana & Indian Logic', 'c. 200 BC - 18th Century', ['nyaya', 'logic', 'india', 'indian', 'epistemology', 'pramana'], null,
    'Nyaya developed a rigorous Indian logic and theory of knowledge, with perception, inference, analogy and testimony as valid means of knowing (pramana). Buddhist logicians like Dignaga and Dharmakirti refined it in dialogue with Nyaya.'),
  I('bhakti-vedanta', 'Bhakti & Theistic Vedanta', '8th - 16th Century', ['bhakti', 'vedanta', 'india', 'indian', 'theism', 'devotion', 'ramanuja'], null,
    'Theistic Vedanta schools, from Ramanuja’s qualified non-dualism to Madhva’s dualism, understand ultimate reality as a personal God to be loved. They shaped the Bhakti movement, expressed in poetry by saints such as Kabir and Mirabai.'),
  I('ahimsa-satyagraha', 'Nonviolence & Satyagraha', '20th Century', ['ahimsa', 'satyagraha', 'nonviolence', 'india', 'indian', 'politics', 'ethics'], null,
    'Satyagraha, “holding firmly to truth”, was Gandhi’s method of principled nonviolent resistance, drawing on Jainism, the Gita, Thoreau and Tolstoy. It inspired civil-rights and independence movements worldwide.'),
  I('logical-positivism', 'Logical Positivism & the Vienna Circle', '1920s - 1950s', ['logical-positivism', 'vienna', 'analytic', 'science', 'verification', 'logic'], null,
    'The Vienna Circle, including Schlick, Carnap and Neurath, held that meaningful statements are either analytic or empirically verifiable, dismissing metaphysics as nonsense. It shaped philosophy of science, though Quine and Popper later criticised its tenets.'),
  I('moral-philosophy-20c', 'Moral Philosophy after 1950', 'Mid-20th - 21st Century', ['ethics', 'virtue-ethics', 'moral-philosophy', 'anscombe', 'foot', 'macintyre', 'nussbaum'], null,
    'Anscombe’s “Modern Moral Philosophy” (1958) sparked a revival of virtue ethics and a critique of rule-based moral theories. Foot, Murdoch, MacIntyre, Taylor and Nussbaum made character, narrative and the emotions central again.'),
  I('speech-act-theory', 'Speech Acts & Philosophy of Language', 'Mid-20th Century', ['language', 'analytic', 'speech-acts', 'ordinary-language', 'austin', 'ryle'], null,
    'Austin’s How to Do Things with Words showed that utterances perform actions such as promising and naming. With Ryle’s critique of the “ghost in the machine”, ordinary-language philosophy reshaped analytic thought.'),
  I('semiotics-lacan', 'Psychoanalytic & Semiotic Theory', '20th Century', ['structuralism', 'psychoanalysis', 'semiotics', 'french', 'language', 'lacan'], null,
    'Lacan reread Freud through Saussure, claiming that the unconscious is structured like a language. Together with Lévi-Strauss and Barthes, he shaped French structuralism and poststructuralism.'),

  // ---- Byzantium, Orthodox, Russia
  T('pseudo-dionysius', 'Pseudo-Dionysius the Areopagite', 'c. 5th - 6th Century AD', ['byzantium', 'orthodox', 'neoplatonism', 'apophatic', 'theology', 'mysticism'], null,
    'Pseudo-Dionysius, writing under an apostolic pseudonym, fused Neoplatonism with Christianity in The Divine Names and Mystical Theology, shaping both apophatic and angelic hierarchies. His works profoundly influenced Eastern and Western mysticism.'),
  T('boethius', 'Boethius', 'c. 477 - 524 AD', ['rome', 'platonism', 'aristotelianism', 'logic', 'consolation', 'roman'], null,
    'Boethius translated and commented on Aristotle’s logic and wrote The Consolation of Philosophy in prison, arguing that true happiness lies in God and virtue. His works served as a bridge between ancient and medieval philosophy.'),
  T('maximus-confessor', 'Maximus the Confessor', 'c. 580 - 662 AD', ['byzantium', 'constantinople', 'orthodox', 'theology', 'neoplatonism', 'mysticism'], null,
    'Maximus the Confessor synthesised Greek philosophy and Christian theology, developing the doctrine of the logoi (rational principles) of creation and theosis. He suffered mutilation and exile defending Christ’s two wills.'),
  T('john-damascene', 'John of Damascus', 'c. 675 - 749 AD', ['damascus', 'byzantium', 'orthodox', 'theology', 'islamic'], null,
    'John of Damascus systematised Greek patristic theology in The Fount of Knowledge and defended icons. Writing under Umayyad rule, he is among the first Christian thinkers to respond to Islam.'),
  T('psellos', 'Michael Psellos', '1018 - c. 1078 AD', ['constantinople', 'byzantium', 'platonism', 'humanism', 'history', 'greek'], null,
    'Michael Psellos, polymath at the Byzantine court, revived Platonic and Neoplatonic studies and wrote the Chronographia. He reshaped the curriculum and showed that classical philosophy could serve imperial culture.'),
  T('gregory-palamas', 'Gregory Palamas', '1296 - 1359 AD', ['mount-athos', 'constantinople', 'byzantium', 'orthodox', 'hesychasm', 'theology'], null,
    'Gregory Palamas defended Hesychast prayer, distinguishing God’s unknowable essence from his knowable uncreated energies. His teaching became normative for Orthodox theology and a counterpoint to Latin scholasticism.'),
  T('plethon', 'Gemistus Plethon', 'c. 1355 - 1452 AD', ['constantinople', 'byzantium', 'platonism', 'florence', 'humanism', 'greek'], null,
    'Plethon, Byzantine Platonist, visited the Council of Florence in 1438 and inspired Cosimo de’ Medici’s Platonic Academy. He wrote on the superiority of Plato over Aristotle and imagined a reformed Greek polity.'),
  T('chaadaev', 'Pyotr Chaadaev', '1794 - 1856 AD', ['moscow', 'russia', 'russian', 'westernizers', 'history', 'politics'], null,
    'Pyotr Chaadaev’s First Philosophical Letter (1836) argued that Russia had contributed nothing to world civilisation, sparking the Slavophile–Westernizer debate. The government declared him officially insane, and he became a symbol of Russian self-critique.'),
  T('khomyakov', 'Alexei Khomyakov', '1804 - 1860 AD', ['moscow', 'russia', 'russian', 'slavophiles', 'orthodox', 'theology'], null,
    'Alexei Khomyakov, lay theologian and Slavophile, developed the concept of sobornost, spiritual community in freedom and love, as the essence of Orthodoxy. He contrasted Russian communal life with Western individualism.'),
  T('herzen', 'Alexander Herzen', '1812 - 1870 AD', ['st-petersburg', 'london', 'russia', 'russian', 'westernizers', 'socialism', 'politics'], null,
    'Alexander Herzen, exile and publisher of The Bell in London, blended Hegelian dialectics and populist socialism, hoping the peasant commune could bypass capitalism. His memoir My Past and Thoughts is a classic of liberal humanism.'),
  T('dostoevsky', 'Fyodor Dostoevsky', '1821 - 1881 AD', ['st-petersburg', 'russia', 'russian', 'existentialism', 'literature', 'orthodox', 'ethics'], null,
    'Fyodor Dostoevsky dramatised radical freedom, nihilism and faith in Notes from Underground, Crime and Punishment and The Brothers Karamazov. His polyphonic novels profoundly shaped existentialism, psychology and theology.'),
  T('tolstoy', 'Leo Tolstoy', '1828 - 1910 AD', ['moscow', 'russia', 'russian', 'nonviolence', 'literature', 'ethics', 'anarchism'], null,
    'Leo Tolstoy turned from novelistic art to a Christian anarchist ethic of nonviolence, expressed in The Kingdom of God Is Within You. His letters influenced Gandhi and his reflections on history and death remain powerful.'),
  T('solovyov', 'Vladimir Solovyov', '1853 - 1900 AD', ['moscow', 'russia', 'russian', 'orthodox', 'sophiology', 'platonism', 'russian-religious-philosophy'], null,
    'Vladimir Solovyov, founder of Russian systematic philosophy, proposed “all-unity” and Divine Sophia, weaving Platonism, German idealism and Christianity. He inspired the Silver Age religious renaissance.'),
  T('fedorov', 'Nikolai Fedorov', '1829 - 1903 AD', ['moscow', 'russia', 'russian', 'cosmism', 'futurism', 'immortality', 'orthodox'], null,
    'Nikolai Fedorov, a Moscow librarian, taught in the Philosophy of the Common Task that humanity must overcome death, resurrect ancestors by science and colonise space. His vision shaped Tsiolkovsky and the space programme.'),
  T('tsiolkovsky', 'Konstantin Tsiolkovsky', '1857 - 1935 AD', ['russia', 'russian', 'cosmism', 'space', 'futurism', 'science', 'technology'], null,
    'Konstantin Tsiolkovsky, rocket-science pioneer, argued humanity must leave Earth, its “cradle”, and wrote of cosmic evolution and panpsychism. He is a patron saint of astronautics and cosmist futurism.'),
  T('vernadsky', 'Vladimir Vernadsky', '1863 - 1945 AD', ['russia', 'russian', 'cosmism', 'ecology', 'science', 'noosphere', 'ukrainian'], null,
    'Vladimir Vernadsky, geochemist, defined the biosphere as a planetary force and, with Teilhard de Chardin, developed the idea of the noosphere, the sphere of human thought transforming Earth. He is a founding figure of ecology.'),
  T('berdyaev', 'Nikolai Berdyaev', '1874 - 1948 AD', ['moscow', 'paris', 'russia', 'russian', 'existentialism', 'personalism', 'orthodox', 'russian-religious-philosophy'], null,
    'Nikolai Berdyaev, exiled Christian existentialist, stressed freedom, creativity and personhood against both Soviet collectivism and bourgeois conformism. His books in Paris, such as Slavery and Freedom, influenced European personalism.'),
  T('shestov', 'Lev Shestov', '1866 - 1938 AD', ['kyiv', 'paris', 'russia', 'russian', 'existentialism', 'faith', 'reason'], null,
    'Lev Shestov pitted “Jerusalem” against “Athens”, arguing that faith and the absurd outweigh rationalist necessity. His dialogue with Kierkegaard and Nietzsche influenced Camus and French existentialism.'),
  T('florensky', 'Pavel Florensky', '1882 - 1937 AD', ['moscow', 'russia', 'russian', 'orthodox', 'mathematics', 'sophiology', 'art'], null,
    'Pavel Florensky, priest, mathematician and art theorist, wrote The Pillar and Ground of the Truth and studied inverse perspective in icons. He was shot in the Soviet camps in 1937.'),
  T('bakhtin', 'Mikhail Bakhtin', '1895 - 1975 AD', ['st-petersburg', 'russia', 'russian', 'dialogue', 'literature', 'language', 'philosophy'], null,
    'Mikhail Bakhtin developed dialogism, polyphony and the carnivalesque in his studies of Dostoevsky and Rabelais, arguing that meaning arises in social interaction. His ideas shaped literary theory, linguistics and cultural studies.'),
  T('lotman', 'Yuri Lotman', '1922 - 1993 AD', ['tartu', 'russia', 'russian', 'semiotics', 'culture', 'structuralism'], null,
    'Yuri Lotman, founder of the Tartu–Moscow semiotic school, introduced the “semiosphere” as the space within which cultures generate meaning. His studies of culture as information systems fed structuralism and cultural semiotics.'),
  T('losev', 'Aleksei Losev', '1893 - 1988 AD', ['moscow', 'russia', 'russian', 'platonism', 'aesthetics', 'neoplatonism', 'orthodox'], null,
    'Aleksei Losev, philologist of Moscow, wrote an eight-volume History of Ancient Aesthetics and defended the “name-glorifiers” of Orthodoxy. He survived Soviet imprisonment and preserved Neoplatonic scholarship.'),
  T('mamardashvili', 'Merab Mamardashvili', '1930 - 1990 AD', ['moscow', 'tbilisi', 'russian', 'phenomenology', 'consciousness', 'kant', 'georgian'], null,
    'Merab Mamardashvili, Georgian philosopher, taught Descartes, Kant and Proust to Soviet audiences and developed a phenomenology of consciousness as an effort to be free. He is a symbol of independent Soviet-era thought.'),

  // ---- Medieval West
  T('eriugena', 'John Scotus Eriugena', 'c. 815 - 877 AD', ['paris', 'neoplatonism', 'scholasticism', 'mysticism', 'medieval', 'irish'], null,
    'John Scotus Eriugena translated Pseudo-Dionysius and wrote the Periphyseon, a Neoplatonic cosmology of nature’s division and return to God. He is a key link between Greek patristics and Latin philosophy.'),
  T('abelard', 'Peter Abelard', '1079 - 1142 AD', ['paris', 'scholasticism', 'logic', 'ethics', 'medieval', 'french'], null,
    'Peter Abelard, brilliant logician of Paris, applied dialectic in Sic et Non and argued that moral worth lies in intention. His famed love affair with Heloise has overshadowed his contribution to nominalism and medieval ethics.'),
  T('hildegard', 'Hildegard of Bingen', '1098 - 1179 AD', ['mysticism', 'medieval', 'german', 'women-philosophers', 'music', 'medicine'], null,
    'Hildegard of Bingen, abbess, composer and naturalist, recorded theological visions in Scivias and wrote on medicine and cosmology. Her notion of viriditas, divine greening power, anticipates ecological theology.'),
  T('albertus-magnus', 'Albertus Magnus', 'c. 1200 - 1280 AD', ['paris', 'cologne', 'scholasticism', 'aristotelianism', 'science', 'german'], null,
    'Albertus Magnus, teacher of Aquinas, commented on all of Aristotle and made empirical observations in botany, zoology and mineralogy. He championed using philosophy and natural science within Christian theology.'),
  T('bonaventure', 'Bonaventure', '1221 - 1274 AD', ['paris', 'scholasticism', 'mysticism', 'platonism', 'franciscan', 'italian'], null,
    'Bonaventure, Franciscan Minister General, wrote The Journey of the Mind into God, combining Augustinian illumination with mystical ascent. He criticised Aristotelianism’s limits and exemplifies the Franciscan school.'),
  T('roger-bacon', 'Roger Bacon', 'c. 1214 - 1292 AD', ['oxford-cambridge', 'paris', 'scholasticism', 'science', 'empiricism', 'optics'], null,
    'Roger Bacon, Franciscan scholar at Oxford and Paris, urged experimental science and mathematics, and wrote on optics and language. His Opus Majus laid out a plan for reforming learning, anticipating early modern methodology.'),
  T('eckhart', 'Meister Eckhart', 'c. 1260 - 1328 AD', ['paris', 'cologne', 'mysticism', 'apophatic', 'german', 'scholasticism'], null,
    'Meister Eckhart, Dominican preacher, taught the birth of God in the soul and “detachment” (Gelassenheit), speaking of the Godhead beyond God. His paradoxical sermons influenced German mysticism and later Heidegger.'),
  T('marsilius', 'Marsilius of Padua', 'c. 1275 - 1342 AD', ['padua', 'italy', 'politics', 'scholasticism', 'secularism', 'law'], null,
    'Marsilius of Padua wrote Defensor Pacis, arguing that political authority derives from the people and that the Church should lack coercive power. His secular theory of sovereignty anticipated modern political thought.'),
  T('christine-de-pizan', 'Christine de Pizan', 'c. 1364 - 1430 AD', ['paris', 'feminism', 'women-philosophers', 'humanism', 'french', 'medieval'], null,
    'Christine de Pizan, widow and professional writer in Paris, wrote The Book of the City of Ladies, defending women’s intellect against misogynist literature. She is often called the first feminist author in the European tradition.'),
  T('nicholas-cusa', 'Nicholas of Cusa', '1401 - 1464 AD', ['mysticism', 'humanism', 'neoplatonism', 'german', 'mathematics', 'italy'], null,
    'Nicholas of Cusa developed “learned ignorance” and the coincidence of opposites, arguing that the universe has no fixed centre. His mathematics of the infinite and his tolerant ecumenism anticipated early modern thought.'),

  // ---- Early modern West
  T('bruno', 'Giordano Bruno', '1548 - 1600 AD', ['naples', 'italy', 'scientific-revolution', 'panpsychism', 'humanism', 'italian'], null,
    'Giordano Bruno, Dominican turned heretic, defended an infinite universe of countless worlds and a pantheist metaphysics. The Inquisition burned him in Rome in 1600, and he became a martyr for free thought.'),
  T('galileo', 'Galileo Galilei', '1564 - 1642 AD', ['italy', 'padua', 'florence', 'scientific-revolution', 'science', 'astronomy', 'italian'], null,
    'Galileo pioneered telescopic astronomy and mathematical physics, arguing that “the book of nature is written in the language of mathematics”. His trial before the Inquisition became the emblem of the conflict between science and authority.'),
  T('grotius', 'Hugo Grotius', '1583 - 1645 AD', ['amsterdam', 'natural-law', 'law', 'politics', 'dutch', 'human-rights'], null,
    'Hugo Grotius, Dutch jurist, wrote On the Law of War and Peace, grounding international law in natural law that would hold “even if God did not exist”. He is a founder of modern international legal thought.'),
  T('newton', 'Isaac Newton', '1643 - 1727 AD', ['oxford-cambridge', 'london', 'scientific-revolution', 'physics', 'science', 'british'], null,
    'Isaac Newton unified terrestrial and celestial mechanics in the Principia and developed calculus and optics. His mechanical universe defined the scientific worldview of the Enlightenment and provoked philosophical debates about space, time and God.'),
  T('vitoria', 'Francisco de Vitoria', 'c. 1483 - 1546 AD', ['salamanca', 'spain', 'natural-law', 'human-rights', 'scholasticism', 'spanish'], null,
    'Francisco de Vitoria, Dominican professor at Salamanca, argued that the indigenous peoples of the Americas possessed natural rights and rightful dominion. His lectures laid foundations for international law and human rights.'),
  T('las-casas', 'Bartolomé de las Casas', '1484 - 1566 AD', ['salamanca', 'latin-america', 'human-rights', 'decolonial', 'spanish', 'liberation'], null,
    'Bartolomé de las Casas, Dominican friar, denounced Spanish atrocities in the Americas and argued for the humanity and rights of indigenous peoples at the Valladolid debate. He is a forerunner of liberation thought.'),
  T('sor-juana', 'Sor Juana Inés de la Cruz', '1648 - 1695 AD', ['latin-america', 'mexico-city', 'feminism', 'women-philosophers', 'poetry', 'spanish'], null,
    'Sor Juana, Mexican nun, poet and polymath, defended women’s right to education in her Reply to Sor Filotea. Her baroque poetry and scientific curiosity make her a pioneering voice of colonial Latin American thought.'),
  T('vico', 'Giambattista Vico', '1668 - 1744 AD', ['naples', 'italy', 'history', 'philosophy-of-history', 'humanism', 'italian'], null,
    'Giambattista Vico argued in the New Science that humans can truly understand history because they made it (verum-factum) and traced cycles of cultural development. He anticipated hermeneutics and historicism.'),
  T('chatelet', 'Émilie du Châtelet', '1706 - 1749 AD', ['paris', 'enlightenment', 'physics', 'women-philosophers', 'french', 'science'], null,
    'Émilie du Châtelet translated and commented on Newton’s Principia into French and defended Leibnizian ideas about force in Institutions of Physics. She is a major figure in the Enlightenment’s scientific culture.'),
  T('herder', 'Johann Gottfried Herder', '1744 - 1803 AD', ['weimar-jena', 'romanticism', 'german', 'language', 'history', 'culture'], null,
    'Johann Gottfried Herder argued that language and culture shape thought and that each people has its own genius (Volksgeist). A critic of Enlightenment universalism, he inspired Romanticism and cultural anthropology.'),
  T('burke', 'Edmund Burke', '1729 - 1797 AD', ['dublin', 'london', 'politics', 'conservatism', 'british', 'enlightenment'], null,
    'Edmund Burke, Irish-born statesman, wrote Reflections on the Revolution in France, defending tradition, prescriptive institutions and gradual reform over abstract rights. He is regarded as a founder of modern conservatism.'),
  T('paine', 'Thomas Paine', '1737 - 1809 AD', ['london', 'paris', 'enlightenment', 'politics', 'rights', 'american'], null,
    'Thomas Paine’s Common Sense and Rights of Man championed republican government and universal rights, answering Burke. His pamphlets energised the American and French Revolutions.'),
  T('condorcet', 'Marquis de Condorcet', '1743 - 1794 AD', ['paris', 'enlightenment', 'progress', 'mathematics', 'politics', 'french'], null,
    'Condorcet, mathematician and revolutionary, wrote a Sketch for a Historical Picture of the Progress of the Human Mind, and defended women’s rights and public education. His vision of infinite perfectibility is an ancestor of modern futurology.'),
  T('reid', 'Thomas Reid', '1710 - 1796 AD', ['edinburgh', 'enlightenment', 'epistemology', 'common-sense', 'scottish', 'british'], null,
    'Thomas Reid founded Scottish Common Sense philosophy, arguing against Hume that perception gives us direct knowledge of the external world. His influence extended to American thought and to analytic philosophy.'),

  // ---- 19th century
  T('comte', 'Auguste Comte', '1798 - 1857 AD', ['paris', 'positivism', 'sociology', 'science', 'french', 'history'], null,
    'Auguste Comte founded positivism, proposing a law of three stages (theological, metaphysical, positive) and coining the term “sociology”. He sought a science of society to guide social reform.'),
  T('tocqueville', 'Alexis de Tocqueville', '1805 - 1859 AD', ['paris', 'politics', 'democracy', 'sociology', 'french', 'liberty'], null,
    'Alexis de Tocqueville analysed American democracy and warned of the “tyranny of the majority” and soft despotism. His Democracy in America remains a classic of political sociology.'),
  T('feuerbach', 'Ludwig Feuerbach', '1804 - 1872 AD', ['berlin', 'german', 'materialism', 'religion', 'critique', 'german-idealism'], null,
    'Ludwig Feuerbach argued in The Essence of Christianity that God is a projection of human nature. His anthropological critique of religion influenced Marx, Engels and later humanism.'),
  T('proudhon', 'Pierre-Joseph Proudhon', '1809 - 1865 AD', ['paris', 'anarchism', 'politics', 'socialism', 'french', 'economics'], null,
    'Pierre-Joseph Proudhon, first self-declared anarchist, asked “What is property?” and answered “theft”, advocating mutualism and federalism. His critique of the state shaped anarchist and socialist thought.'),
  T('bakunin', 'Mikhail Bakunin', '1814 - 1876 AD', ['russia', 'russian', 'anarchism', 'politics', 'revolution', 'paris'], null,
    'Mikhail Bakunin, Russian revolutionary, opposed both capitalism and state socialism, famously feuding with Marx in the First International. He championed collectivist anarchism and the abolition of authority.'),
  T('stirner', 'Max Stirner', '1806 - 1856 AD', ['berlin', 'german', 'anarchism', 'individualism', 'nihilism', 'german-idealism'], null,
    'Max Stirner’s The Ego and Its Own attacked every “spook”, from God to humanity and the state, defending radical egoism. He influenced individualist anarchism, existentialism and Nietzsche scholarship.'),
  T('darwin', 'Charles Darwin', '1809 - 1882 AD', ['london', 'oxford-cambridge', 'science', 'evolution', 'british', 'materialism'], null,
    'Charles Darwin’s On the Origin of Species explained the diversity of life by natural selection, transforming biology and challenging teleology and human exceptionalism. His theory reshaped ethics, psychology and philosophy.'),
  T('spencer', 'Herbert Spencer', '1820 - 1903 AD', ['london', 'evolution', 'sociology', 'liberty', 'british', 'positivism'], null,
    'Herbert Spencer applied evolution to society, coining “survival of the fittest” and defending laissez-faire liberalism. His synthetic philosophy was hugely influential in his day and later heavily criticised.'),
  T('dilthey', 'Wilhelm Dilthey', '1833 - 1911 AD', ['berlin', 'german', 'hermeneutics', 'history', 'life-philosophy', 'heidelberg'], null,
    'Wilhelm Dilthey distinguished the human sciences, which seek understanding (Verstehen), from natural sciences that explain. His “critique of historical reason” paved the way for hermeneutics and existential phenomenology.'),
  T('durkheim', 'Émile Durkheim', '1858 - 1917 AD', ['paris', 'sociology', 'positivism', 'french', 'religion', 'society'], null,
    'Émile Durkheim established sociology as a discipline, studying social facts, suicide and the division of labour. His idea of collective effervescence explained religion as society’s self-representation.'),
  T('simmel', 'Georg Simmel', '1858 - 1918 AD', ['berlin', 'german', 'sociology', 'modernism', 'money', 'urban'], null,
    'Georg Simmel analysed the metropolis, money and the stranger, focusing on forms of social interaction. His Philosophy of Money shows how monetary exchange reshapes culture and personality.'),
  T('freud', 'Sigmund Freud', '1856 - 1939 AD', ['vienna', 'psychoanalysis', 'mind', 'unconscious', 'austrian', 'modernism'], null,
    'Sigmund Freud founded psychoanalysis, positing unconscious drives, repression, dreams and the Oedipus complex. His theories transformed psychology, culture and philosophy, even where they are scientifically contested.'),
  T('jung', 'Carl Gustav Jung', '1875 - 1961 AD', ['zurich', 'psychoanalysis', 'mind', 'archetypes', 'swiss', 'mysticism'], null,
    'Carl Jung, Swiss psychiatrist, proposed the collective unconscious, archetypes and individuation, drawing on mythology and religion. His psychology influenced art, literature and the study of religion.'),
  T('brentano', 'Franz Brentano', '1838 - 1917 AD', ['vienna', 'phenomenology', 'mind', 'austrian', 'intentionality', 'aristotelianism'], null,
    'Franz Brentano revived the scholastic notion of intentionality, asserting that all mental acts are directed at objects. His students included Husserl, Freud and Meinong, and he founded the Austrian tradition of descriptive psychology.'),
  T('whitehead', 'Alfred North Whitehead', '1861 - 1947 AD', ['oxford-cambridge', 'boston-harvard', 'process', 'panpsychism', 'logic', 'british'], null,
    'Alfred North Whitehead co-wrote Principia Mathematica and later developed process philosophy in Process and Reality, seeing reality as events and experiential occasions. His work inspires panpsychism and ecological thought.'),
  T('moore', 'G.E. Moore', '1873 - 1958 AD', ['oxford-cambridge', 'analytic', 'ethics', 'common-sense', 'british', 'logic'], null,
    'G.E. Moore, Cambridge philosopher, rebutted idealism with “common sense” and argued in Principia Ethica that “good” is indefinable (the naturalistic fallacy). He helped launch analytic philosophy.'),
  T('carnap', 'Rudolf Carnap', '1891 - 1970 AD', ['vienna', 'logical-positivism', 'analytic', 'logic', 'german', 'science'], null,
    'Rudolf Carnap, a leader of the Vienna Circle, sought a logical reconstruction of science in The Logical Structure of the World and criticised metaphysics as meaningless. Later he developed inductive logic and semantics.'),
  T('schlick', 'Moritz Schlick', '1882 - 1936 AD', ['vienna', 'logical-positivism', 'analytic', 'physics', 'german', 'epistemology'], null,
    'Moritz Schlick, founder of the Vienna Circle, defended verificationism and a naturalistic ethics. He was murdered by a student on the University of Vienna’s steps in 1936.'),
  T('ayer', 'A.J. Ayer', '1910 - 1989 AD', ['oxford-cambridge', 'logical-positivism', 'analytic', 'british', 'epistemology', 'language'], null,
    'A.J. Ayer introduced logical positivism to the English-speaking world in Language, Truth and Logic, promoting the verification principle and emotivism in ethics. He remained an outspoken empiricist and public intellectual.'),
  T('ryle', 'Gilbert Ryle', '1900 - 1976 AD', ['oxford-cambridge', 'ordinary-language', 'analytic', 'mind', 'british', 'speech-acts'], null,
    'Gilbert Ryle attacked Cartesian dualism as the “ghost in the machine” in The Concept of Mind, arguing that mental terms describe dispositions to behave. He was a leader of Oxford ordinary-language philosophy.'),
  T('austin', 'J.L. Austin', '1911 - 1960 AD', ['oxford-cambridge', 'ordinary-language', 'speech-acts', 'analytic', 'british', 'language'], null,
    'J.L. Austin developed speech-act theory in How to Do Things with Words, distinguishing locutionary, illocutionary and perlocutionary acts. His careful attention to ordinary usage transformed philosophy of language.'),
  T('anscombe', 'G.E.M. Anscombe', '1919 - 2001 AD', ['oxford-cambridge', 'ethics', 'virtue-ethics', 'moral-philosophy', 'women-philosophers', 'british'], null,
    'Elizabeth Anscombe, student and translator of Wittgenstein, wrote Intention and “Modern Moral Philosophy”, which coined “consequentialism” and sparked virtue ethics’ revival. She also opposed Truman’s honorary degree in Oxford.'),
  T('foot', 'Philippa Foot', '1920 - 2010 AD', ['oxford-cambridge', 'ethics', 'virtue-ethics', 'moral-philosophy', 'women-philosophers', 'british'], null,
    'Philippa Foot introduced the trolley problem and defended a naturalist virtue ethics in Natural Goodness. She helped revive Aristotelian approaches to moral philosophy.'),
  T('murdoch', 'Iris Murdoch', '1919 - 1999 AD', ['oxford-cambridge', 'ethics', 'moral-philosophy', 'platonism', 'women-philosophers', 'british'], null,
    'Iris Murdoch, philosopher and novelist, argued in The Sovereignty of Good that moral life is a matter of attention and love, with the Good as a Platonic centre. She countered existentialism and behaviourism in ethics.'),
  T('macintyre', 'Alasdair MacIntyre', '1929 - 2025 AD', ['edinburgh', 'ethics', 'virtue-ethics', 'moral-philosophy', 'scottish', 'aristotelianism'], null,
    'Alasdair MacIntyre argued in After Virtue that modern moral discourse is fragmentary and that we must revive Aristotelian virtues in tradition-constituted communities. His work reshaped communitarian ethics.'),
  T('taylor', 'Charles Taylor', '1931 - Present', ['montreal', 'hermeneutics', 'ethics', 'secularism', 'canadian', 'moral-philosophy'], null,
    'Charles Taylor, Canadian philosopher, wrote Sources of the Self and A Secular Age, charting the rise of modern identity and secularity. He defends a politics of recognition and a hermeneutic conception of the self.'),
  T('nussbaum', 'Martha Nussbaum', '1947 - Present', ['chicago', 'ethics', 'virtue-ethics', 'moral-philosophy', 'women-philosophers', 'capabilities'], null,
    'Martha Nussbaum develops the capabilities approach with Amartya Sen, defends the role of emotions in ethics, and applies Aristotle and Stoicism to modern justice. She writes on education, law and global inequality.'),
  T('weil', 'Simone Weil', '1909 - 1943 AD', ['paris', 'mysticism', 'ethics', 'women-philosophers', 'french', 'platonism'], null,
    'Simone Weil, philosopher and activist, joined factory labour, wrote on attention, affliction and grace, and joined the Resistance. Her posthumous works fuse Platonism, Christianity and radical political ethics.'),
  T('gramsci', 'Antonio Gramsci', '1891 - 1937 AD', ['italy', 'marxism', 'politics', 'italian', 'hegemony', 'critique'], null,
    'Antonio Gramsci, imprisoned by Mussolini, developed the concept of cultural hegemony in his Prison Notebooks, analysing how ruling classes maintain consent. His thought influenced cultural studies and postcolonial theory.'),
  T('lenin', 'Vladimir Lenin', '1870 - 1924 AD', ['st-petersburg', 'moscow', 'russia', 'russian', 'marxism', 'politics', 'revolution'], null,
    'Vladimir Lenin adapted Marxism to Russian conditions, developing vanguard-party theory and the analysis of imperialism, and led the 1917 Bolshevik revolution. His legacy remains deeply contested in political thought.'),
  T('fanon', 'Frantz Fanon', '1925 - 1961 AD', ['paris', 'africa', 'postcolonial', 'decolonial', 'psychiatry', 'french', 'politics'], null,
    'Frantz Fanon, psychiatrist from Martinique, analysed colonial alienation in Black Skin, White Masks and defended anti-colonial struggle in The Wretched of the Earth. He is a foundational figure of postcolonial theory.'),
  T('said', 'Edward Said', '1935 - 2003 AD', ['new-york', 'postcolonial', 'critique', 'literature', 'palestinian', 'orientalism'], null,
    'Edward Said’s Orientalism argued that Western scholarship constructed the “Orient” as an inferior other serving imperial power. The book launched postcolonial studies and critical debates about representation.'),
  T('spivak', 'Gayatri Chakravorty Spivak', '1942 - Present', ['new-york', 'postcolonial', 'feminism', 'deconstruction', 'indian', 'critique'], null,
    'Gayatri Spivak, in “Can the Subaltern Speak?”, questioned how marginalised voices can be represented without erasure. She combines deconstruction, Marxism and feminism in postcolonial critique.'),
  T('lacan', 'Jacques Lacan', '1901 - 1981 AD', ['paris', 'psychoanalysis', 'semiotics-lacan', 'structuralism', 'french', 'language'], null,
    'Jacques Lacan reread Freud through structural linguistics, proposing the mirror stage and the registers of the Real, Symbolic and Imaginary. His seminars shaped French theory, film studies and feminism.'),
  T('saussure', 'Ferdinand de Saussure', '1857 - 1913 AD', ['geneva', 'structuralism', 'semiotics', 'language', 'swiss', 'linguistics'], null,
    'Ferdinand de Saussure treated language as a system of signs defined by differences, distinguishing langue from parole and signifier from signified. His Course in General Linguistics launched structuralism.'),
  T('levi-strauss', 'Claude Lévi-Strauss', '1908 - 2009 AD', ['paris', 'structuralism', 'anthropology', 'french', 'myth', 'semiotics'], null,
    'Claude Lévi-Strauss applied structural linguistics to kinship and myth, seeking universal mental structures in human cultures. His work in The Savage Mind challenged ethnocentric views of “primitive” thought.'),
  T('barthes', 'Roland Barthes', '1915 - 1980 AD', ['paris', 'structuralism', 'semiotics', 'literature', 'french', 'postmodernism'], null,
    'Roland Barthes decoded modern myths in Mythologies and proclaimed “the death of the author”, shifting meaning to the reader. He moved from structuralism toward poststructuralist play of the text.'),
  T('ricoeur', 'Paul Ricoeur', '1913 - 2005 AD', ['paris', 'hermeneutics', 'phenomenology', 'french', 'narrative', 'ethics'], null,
    'Paul Ricoeur united phenomenology and hermeneutics, developing narrative identity and a philosophy of memory and recognition. His Oneself as Another examines selfhood in relation to ethical responsibility.'),
  T('lyotard', 'Jean-François Lyotard', '1924 - 1998 AD', ['paris', 'postmodernism', 'french', 'knowledge', 'critique', 'language'], null,
    'Jean-François Lyotard defined the postmodern condition as “incredulity toward metanarratives” in his 1979 report on knowledge. His work explores language games, the sublime and the différend.'),
  T('irigaray', 'Luce Irigaray', '1930 - Present', ['paris', 'feminism', 'psychoanalysis', 'postmodernism', 'women-philosophers', 'belgian'], null,
    'Luce Irigaray critiques the masculine bias of Western philosophy and psychoanalysis, advocating a sexuate difference and a feminine symbolic. Her books, such as Speculum of the Other Woman, shaped French feminism.'),
  T('kristeva', 'Julia Kristeva', '1941 - Present', ['paris', 'feminism', 'psychoanalysis', 'semiotics', 'women-philosophers', 'bulgarian'], null,
    'Julia Kristeva, Bulgarian-French theorist, introduced intertextuality, the abject and the semiotic–symbolic dialectic. Her work links psychoanalysis, linguistics and feminism.'),
  T('zizek', 'Slavoj Žižek', '1949 - Present', ['ljubljana', 'marxism', 'psychoanalysis', 'critique', 'slovenian', 'postmodernism'], null,
    'Slavoj Žižek combines Lacan, Hegel and Marx to analyse ideology, popular culture and contemporary politics. His prolific, provocative writing has made him one of the best-known living philosophers.'),
  T('badiou', 'Alain Badiou', '1937 - Present', ['paris', 'marxism', 'mathematics', 'french', 'ontology', 'politics'], null,
    'Alain Badiou, in Being and Event, identifies ontology with mathematics (set theory) and describes truth-producing “events” in politics, art, science and love. He defends universalism against postmodern relativism.'),
  T('agamben', 'Giorgio Agamben', '1942 - Present', ['italy', 'politics', 'critique', 'italian', 'biopolitics', 'foucault'], null,
    'Giorgio Agamben’s Homo Sacer analyses “bare life”, the state of exception and biopolitical sovereignty. Drawing on Foucault, Arendt and Benjamin, he diagnoses the camp as a paradigm of modernity.'),
  T('sloterdijk', 'Peter Sloterdijk', '1947 - Present', ['karlsruhe', 'german', 'critique', 'technology', 'spheres', 'modernism'], null,
    'Peter Sloterdijk wrote the Critique of Cynical Reason and the trilogy Spheres, exploring humans as beings who live in enclosed “bubbles”. He engages with technology, anthropotechnics and post-metaphysical thought.'),
  T('weil-eric', 'Eric Voegelin', '1901 - 1985 AD', ['vienna', 'politics', 'history', 'gnosticism', 'austrian', 'order'], null,
    'Eric Voegelin analysed modern political movements as “gnostic” immanentisations of religious symbols, in his History of Order. He stressed the experience of transcendence as the basis of political order.'),

  // ---- India
  T('chanakya', 'Chanakya (Kautilya)', 'c. 350 - 275 BC', ['india', 'indian', 'politics', 'statecraft', 'economics', 'political-realism', 'ancient'], null,
    'Chanakya, advisor to Chandragupta Maurya, is traditionally credited with the Arthashastra, a manual of statecraft, economics and strategy. Its pragmatic analysis of power is often compared with Machiavelli and Thucydides.'),
  T('mahavira', 'Mahavira', 'c. 599 - 527 BC', ['india', 'indian', 'jainism', 'ahimsa', 'ethics', 'ancient'], null,
    'Mahavira, the last Jain Tirthankara, taught strict non-violence, truthfulness and non-attachment as the path to liberation. His teaching of many-sided truth shaped Indian pluralism.'),
  T('patanjali', 'Patanjali', 'c. 2nd Century BC - 4th Century AD', ['india', 'indian', 'yoga', 'samkhya', 'meditation', 'consciousness', 'ancient'], null,
    'Patanjali systematised the eight limbs of yoga in the Yoga Sutras, aiming at the cessation of mental fluctuations. His text underlies both classical yoga philosophy and modern yoga practice.'),
  T('asanga', 'Asanga', 'c. 4th Century AD', ['india', 'nalanda', 'buddhism', 'yogacara', 'mind', 'indian'], null,
    'Asanga, half-brother of Vasubandhu, co-founded Yogacara with works such as the Yogacarabhumi and Mahayanasamgraha. He developed the storehouse consciousness and the theory of three natures.'),
  T('dignaga', 'Dignaga', 'c. 480 - 540 AD', ['india', 'nalanda', 'buddhism', 'logic', 'epistemology', 'nyaya-pramana', 'indian'], null,
    'Dignaga founded Buddhist epistemology and logic, arguing that there are only two valid means of knowledge, perception and inference. His Pramanasamuccaya inspired Dharmakirti and Tibetan scholasticism.'),
  T('dharmakirti', 'Dharmakirti', 'c. 6th - 7th Century AD', ['india', 'nalanda', 'buddhism', 'logic', 'epistemology', 'nyaya-pramana', 'indian'], null,
    'Dharmakirti elaborated Dignaga’s logic in the Pramanavarttika, defending the apoha theory of meaning and a causal account of knowledge. His work is central to Tibetan Buddhist philosophy.'),
  T('candrakirti', 'Candrakirti', 'c. 600 - 650 AD', ['india', 'nalanda', 'buddhism', 'sunyata', 'madhyamaka', 'indian'], null,
    'Candrakirti defended the Prasangika Madhyamaka reading of Nagarjuna, arguing that emptiness is shown by reductio arguments without positing independent theses. His commentaries are foundational for Tibetan Buddhism.'),
  T('ramanuja', 'Ramanuja', 'c. 1017 - 1137 AD', ['india', 'indian', 'vedanta', 'bhakti', 'theism', 'bhakti-vedanta'], null,
    'Ramanuja developed Vishishtadvaita, qualified non-dualism, in which souls and the world are real attributes of Brahman, a personal God. He challenged Shankara’s illusionism and promoted devotional Vaishnavism.'),
  T('madhva', 'Madhvacharya', 'c. 1238 - 1317 AD', ['india', 'indian', 'vedanta', 'bhakti', 'dualism', 'bhakti-vedanta'], null,
    'Madhva founded Dvaita Vedanta, asserting an eternal five-fold distinction between God, souls and matter. His school stresses devotion to Vishnu and rejects the identity of self and Brahman.'),
  T('kabir', 'Kabir', 'c. 1440 - 1518 AD', ['india', 'delhi', 'indian', 'bhakti', 'sufism', 'poetry', 'varanasi'], null,
    'Kabir, a weaver-poet of Varanasi, criticised caste, ritualism and sectarian divisions among Hindus and Muslims in his couplets. His mystic poetry blends Bhakti and Sufi currents and is central to North Indian spirituality.'),
  T('vivekananda', 'Swami Vivekananda', '1863 - 1902 AD', ['india', 'indian', 'vedanta', 'hinduism', 'delhi', 'reform', 'boston-harvard'], null,
    'Swami Vivekananda introduced Vedanta and yoga to the West at the 1893 Parliament of the World’s Religions. He promoted a universal religion, social service and national awakening in India.'),
  T('tagore', 'Rabindranath Tagore', '1861 - 1941 AD', ['india', 'indian', 'poetry', 'education', 'humanism', 'delhi', 'bengal'], null,
    'Rabindranath Tagore, poet and Nobel laureate, wrote of humanism, education and nationalism, founding the Visva-Bharati university. His debates with Gandhi and Einstein explored the relation of science, spirit and politics.'),
  T('gandhi', 'Mohandas Gandhi', '1869 - 1948 AD', ['india', 'indian', 'delhi', 'nonviolence', 'satyagraha', 'ethics', 'jainism', 'politics'], null,
    'Mohandas Gandhi led India’s independence movement through satyagraha, nonviolent civil disobedience, drawing on the Gita, Jainism, Tolstoy and Thoreau. His Hind Swaraj criticised industrial civilisation and imagined self-rule.'),
  T('aurobindo', 'Sri Aurobindo', '1872 - 1950 AD', ['india', 'indian', 'vedanta', 'evolution', 'integral-yoga', 'mysticism'], null,
    'Sri Aurobindo moved from revolutionary politics to an Integral Yoga and evolutionary mysticism, arguing in The Life Divine that consciousness is evolving toward a supramental stage. He blended Vedanta with Western evolutionary thought.'),
  T('ambedkar', 'B.R. Ambedkar', '1891 - 1956 AD', ['india', 'indian', 'delhi', 'justice', 'politics', 'buddhism', 'rights'], null,
    'B.R. Ambedkar, jurist and architect of India’s Constitution, analysed caste in Annihilation of Caste and led Dalit emancipation. He converted to Buddhism, reinterpreting it as a social philosophy of equality.'),
  T('radhakrishnan', 'Sarvepalli Radhakrishnan', '1888 - 1975 AD', ['india', 'indian', 'oxford-cambridge', 'vedanta', 'comparative-philosophy', 'politics'], null,
    'Sarvepalli Radhakrishnan, Oxford professor and India’s second president, interpreted Indian philosophy for global audiences and argued for the compatibility of religious experience and reason. He promoted dialogue between East and West.'),

  // ---- East Asia
  T('zhu-xi', 'Zhu Xi', '1130 - 1200 AD', ['china', 'chinese', 'neo-confucianism', 'confucianism', 'metaphysics', 'song-dynasty'], null,
    'Zhu Xi synthesised Neo-Confucian thought, defining the Four Books as the core canon and developing the doctrine of principle (li) and vital energy (qi). His commentaries dominated the imperial examinations for centuries.'),
  T('wang-yangming', 'Wang Yangming', '1472 - 1529 AD', ['china', 'chinese', 'neo-confucianism', 'ming-dynasty', 'mind', 'ethics'], null,
    'Wang Yangming taught the unity of knowledge and action and that principle resides in the mind, rejecting purely book-based study. His “School of Mind” influenced Japanese and Korean thought.'),
  T('dogen', 'Dogen Zenji', '1200 - 1253 AD', ['japan', 'japanese', 'buddhism', 'zen', 'time', 'kyoto'], null,
    'Dogen, founder of Soto Zen in Japan, taught shikantaza (just sitting) and argued in the Shobogenzo that practice and enlightenment are one. His reflections on being-time anticipate modern phenomenology.'),
  T('nishitani', 'Nishitani Keiji', '1900 - 1990 AD', ['kyoto', 'japan', 'japanese', 'kyoto-school', 'nothingness', 'zen', 'existentialism'], null,
    'Nishitani Keiji, Kyoto School philosopher, wrote Religion and Nothingness, confronting nihilism with Zen’s “absolute emptiness”. He engaged deeply with Nietzsche, Heidegger and Meister Eckhart.'),
  T('watsuji', 'Watsuji Tetsuro', '1889 - 1960 AD', ['tokyo', 'japan', 'japanese', 'ethics', 'climate', 'phenomenology'], null,
    'Watsuji Tetsuro defined human existence as “betweenness” (aidagara) and analysed how climate shapes cultures in Fudo. His Ethics reframes the person as relational, challenging Western individualism.'),
  T('tanabe', 'Tanabe Hajime', '1885 - 1962 AD', ['kyoto', 'japan', 'japanese', 'kyoto-school', 'logic', 'ethics', 'buddhism'], null,
    'Tanabe Hajime developed the “logic of species” and later a philosophy of metanoetics, based on repentance and “other-power” in Pure Land Buddhism. He debated Nishida and responded to wartime tragedy.'),

  // ---- Africa & global south
  T('wiredu', 'Kwasi Wiredu', '1931 - 2022 AD', ['africa', 'african', 'accra', 'analytic', 'decolonial', 'epistemology', 'ethics'], null,
    'Kwasi Wiredu, Ghanaian philosopher, called for the “conceptual decolonisation” of African thought and analysed consensus democracy in Akan culture. He built bridges between analytic philosophy and African tradition.'),
  T('gyekye', 'Kwame Gyekye', '1939 - 2019 AD', ['africa', 'african', 'accra', 'communitarianism', 'ethics', 'ubuntu', 'politics'], null,
    'Kwame Gyekye developed “moderate communitarianism”, arguing that persons are both communal and autonomous, drawing on Akan ethics. His work on tradition and modernity is central to contemporary African philosophy.'),
  T('senghor', 'Léopold Sédar Senghor', '1906 - 2001 AD', ['paris', 'africa', 'african', 'negritude', 'poetry', 'politics', 'postcolonial'], null,
    'Léopold Senghor, poet and first president of Senegal, co-founded Négritude, asserting African cultural values and intuitive reason against colonial denigration. He sought a “civilisation of the universal”.'),
  T('mbembe', 'Achille Mbembe', '1957 - Present', ['africa', 'african', 'postcolonial', 'johannesburg', 'critique', 'necropolitics'], null,
    'Achille Mbembe, Cameroonian historian-philosopher, coined “necropolitics”, analysing how states decide who may live or die. His Critique of Black Reason explores race, colonialism and planetary futures.'),
  T('freire', 'Paulo Freire', '1921 - 1997 AD', ['latin-america', 'brazil', 'liberation', 'education', 'liberation-philosophy', 'marxism'], null,
    'Paulo Freire’s Pedagogy of the Oppressed criticises “banking” education and proposes dialogical teaching that fosters conscientização, critical consciousness. His literacy campaigns shaped critical pedagogy worldwide.'),
  T('dussel', 'Enrique Dussel', '1934 - 2023 AD', ['latin-america', 'mexico-city', 'liberation', 'liberation-philosophy', 'decolonial', 'levinas'], null,
    'Enrique Dussel founded the philosophy of liberation, reading Levinas and Marx from the perspective of Latin America’s “exteriority”. He argued modernity began with the conquest of the Americas.'),
  T('mariategui', 'José Carlos Mariátegui', '1894 - 1930 AD', ['latin-america', 'peru', 'marxism', 'indigenous', 'politics', 'decolonial'], null,
    'José Carlos Mariátegui, Peruvian Marxist, wrote Seven Interpretive Essays on Peruvian Reality, linking socialism to indigenous communal traditions. He is a pioneer of Latin American Marxism.')
);

