// ---------------------------------------------------------------------
//  ASSEMBLY — merge legacy + new data, derive school links, validate
// ---------------------------------------------------------------------
const linkKey = (a, b) => (a < b ? a + '|' + b : b + '|' + a);

const buildGraph = () => {
  const nodes = [];
  const seen = new Set();
  for (const n of [...LEGACY_NODES, ...NODES]) {
    if (seen.has(n.id)) continue;
    seen.add(n.id);
    nodes.push({ ...n, tags: [...new Set((n.tags || []).map((t) => String(t).toLowerCase()))] });
  }

  const links = [];
  const edges = new Set();
  const add = (s, t, label) => {
    if (!s || !t || s === t || !seen.has(s) || !seen.has(t)) return;
    const k = linkKey(s, t);
    if (edges.has(k)) return;
    edges.add(k);
    links.push({ source: s, target: t, label });
  };
  LEGACY_LINKS.forEach((l) => add(l.source, l.target, l.label));
  LINKS.forEach(([s, t, label]) => add(ref(s), ref(t), label));

  // thinkers -> the school/idea their tags name
  for (const n of nodes) {
    if (n.category !== 'thinker') continue;
    for (const tag of n.tags) add(n.id, 'idea-' + tag, 'Associated School');
  }

  // anything still isolated gets attached to an idea sharing a tag
  const deg = new Map(nodes.map((n) => [n.id, 0]));
  links.forEach((l) => { deg.set(l.source, deg.get(l.source) + 1); deg.set(l.target, deg.get(l.target) + 1); });
  for (const n of nodes) {
    if (deg.get(n.id) > 0) continue;
    const host = nodes.find((m) => m.id !== n.id && m.category === 'idea' && m.tags.some((t) => n.tags.includes(t)));
    if (host) add(n.id, host.id, 'Related');
  }
  return { nodes, links };
};

const GRAPH = buildGraph();
export const GRAPH_NODES = GRAPH.nodes;
export const GRAPH_LINKS = GRAPH.links;

/** Nodes with a derived `connectionsCount`; links are copied so callers can mutate them. */
export const getEnrichedGraphData = () => {
  const counts = new Map();
  GRAPH_LINKS.forEach((l) => {
    counts.set(l.source, (counts.get(l.source) || 0) + 1);
    counts.set(l.target, (counts.get(l.target) || 0) + 1);
  });
  return {
    nodes: GRAPH_NODES.map((n) => ({ ...n, connectionsCount: counts.get(n.id) || 0 })),
    links: GRAPH_LINKS.map((l) => ({ ...l })),
  };
};